/* The data of the pages about his world and his reading, loaded only by those pages (after data-built.js):
   AKT.library — «مكتبته»: books, writers, films and music he praised, from his own articles (post: a blog post id) or interviews;
   AKT.refaatLife — «يوميات رفعت إسماعيل»: Refaat Ismail's life as Ma Wara' al-Tabi'a tells it (issue: mwt-<n>);
   AKT.creatures — «وحوش وأساطير»: the monsters and legends of the series, with the folklore behind each;
   AKT.tanta — «طنطا»: the places of his city tied to him, from news reports and his own columns (kind: home|school|university|hospital|mosque|grave|memorial|event|fiction|other);
   AKT.handwriting — «بخط يده»: the published reports of his signatures, dedications and notes (linked, not copied);
   AKT.glossary — «قاموس العرّاب»: the phrases readers know him and his heroes by (who: refaat|abeer|alaa|akt|other; where: an issue or a work).
   Each entry names its source; gathered and checked 2026-10-31. */
window.AKT = window.AKT || {};
window.AKT.library = [{"kind":"book","title":{"ar":"الثلاثية","en":"The Cairo Trilogy"},"by":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"year":1956,"said":{"ar":"عدّها تحفة كثيفة وممتعة جدًا في الوقت نفسه، ورأى أن محفوظ يستحق تقديرًا أكبر.","en":"He called it a dense masterpiece that is also hugely enjoyable, and said Mahfouz deserves more credit."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"الشحاذ","en":"The Beggar"},"by":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"year":1965,"said":{"ar":"قال إنها سببت له أزمة وجودية لا بأس بها، وإن سحر «الطريق» و«اللص والكلاب» يصعب الإفلات منه.","en":"He said it gave him a real existential crisis, and that the spell of The Search and The Thief and the Dogs is hard to escape."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"رحلة ابن فطومة","en":"The Journey of Ibn Fattouma"},"by":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"year":1983,"said":{"ar":"رأى أن «السيميائي» لكويلو نسخة باهتة منها.","en":"He said Coelho's The Alchemist is only a pale copy of it."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"writer","title":{"ar":"نجيب محفوظ","en":"Naguib Mahfouz"},"by":null,"year":null,"said":{"ar":"انحاز إليه في معركة «الشعر أم الرواية» ورأى أنه كان على حق في دفاعه عن فن الرواية.","en":"In the old poetry-versus-novel quarrel he sided with Mahfouz, who he felt was right to defend the novel."},"post":"8408614563219517768","source":"https://aktowfik.blogspot.com/2015/06/blog-post_16.html"},{"kind":"book","title":{"ar":"الجريمة والعقاب","en":"Crime and Punishment"},"by":{"ar":"فيودور دستويفسكي","en":"Fyodor Dostoevsky"},"year":1866,"said":{"ar":"عمل عملاق أدخله عالم الأدب الروسي، يجعلك تسكن عقل البطل.","en":"A giant of a book that pulled him into Russian literature by putting you inside the hero's mind."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"writer","title":{"ar":"أنطون تشيخوف","en":"Anton Chekhov"},"by":null,"year":null,"said":{"ar":"أقوى من أثّر فيه مبكرًا، حتى صار يرى الحياة بعين «تشيخوفية»، ويسميه سيد الأطباء الأدباء.","en":"His strongest early influence — he came to see life through a 'Chekhovian' eye — and the master of doctor-writers."},"post":"4386207679737144707","source":"https://aktowfik.blogspot.com/2016/10/blog-post_5.html"},{"kind":"book","title":{"ar":"التفاحة والجمجمة","en":"The Apple and the Skull"},"by":{"ar":"محمد عفيفي","en":"Mohamed Afifi"},"year":null,"said":{"ar":"رواية عميقة رمزية عن الحياة والوجود، وفي الوقت نفسه مضحكة جدًا.","en":"Deep and symbolic about life and existence, yet very funny."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"ابنة الحظ","en":"Daughter of Fortune"},"by":{"ar":"إيزابيل الليندي","en":"Isabel Allende"},"year":1999,"said":{"ar":"من أجمل ما قرأ في سن متأخرة، وذكّرته بمتعة القراءة نفسها (ومعها «صورة قديمة»).","en":"One of the best books of his later reading life — with Portrait in Sepia — it reminded him of the sheer joy of reading."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"1984","en":"Nineteen Eighty-Four"},"by":{"ar":"جورج أورويل","en":"George Orwell"},"year":1949,"said":{"ar":"مزيج من الخيال العلمي والمغامرة والسياسة، ترجمه بنفسه إلى العربية، ويسمي أورويل عبقريًا.","en":"A blend of science fiction, adventure and politics that he translated himself; he called Orwell a genius."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"book","title":{"ar":"ميزري (الشيطانة)","en":"Misery"},"by":{"ar":"ستيفن كينج","en":"Stephen King"},"year":1987,"said":{"ar":"أول رواية قرأها لكينج أثناء عمله في السعودية، ثم ترجمها بعنوان «الشيطانة».","en":"The first King novel he read, while working in Saudi Arabia; he later translated it as Al-Shaytana."},"post":"2247351448991649384","source":"https://aktowfik.blogspot.com/2016/09/1.html"},{"kind":"writer","title":{"ar":"ستيفن كينج","en":"Stephen King"},"by":null,"year":null,"said":{"ar":"قال إنه مقتنع تمامًا بفكرة كينج أن كاتب الرعب يرسم «دائرة سحرية» تحميه.","en":"He said he fully shared King's idea that a horror writer draws a 'magic circle' to protect himself and his own."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"ثم لم يبق أحد (جزيرة الموت)","en":"And Then There Were None"},"by":{"ar":"أجاثا كريستي","en":"Agatha Christie"},"year":1939,"said":{"ar":"أول رواية قرأها لكريستي، وأبقته مذعورًا لا ينام أيامًا.","en":"His first Christie novel — it kept him frightened and sleepless for days."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"حذار من الشفقة","en":"Beware of Pity"},"by":{"ar":"ستيفان زفايج","en":"Stefan Zweig"},"year":1939,"said":{"ar":"رواية عن الشفقة التي تدفع إلى تضحية تحطم الطرفين، وذكر معها «ماجلان» و«لاعب الشطرنج».","en":"A novel on how pity-driven sacrifice can wreck both sides; he also named Magellan and The Chess Player among Zweig's wonders."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"writer","title":{"ar":"يوسف إدريس","en":"Yusuf Idris"},"by":null,"year":null,"said":{"ar":"«عبقري لم يجد الزمان بمثله إلا نادرًا»، ورأى نوبل أضيق أفقًا من أن تتشرف به.","en":"'A genius the age rarely produces' — he thought the Nobel too narrow to have honoured him."},"post":"5228172907938781168","source":"https://aktowfik.blogspot.com/2014/07/3.html"},{"kind":"book","title":{"ar":"العيب","en":"Al-Eib (The Shame)"},"by":{"ar":"يوسف إدريس","en":"Yusuf Idris"},"year":1962,"said":{"ar":"عدّها مع «الحرام» من الروايات المهمة التي أثرت فيه.","en":"He listed it, with Al-Haram, among the novels that marked him."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"ثلاثية غرناطة","en":"Granada Trilogy"},"by":{"ar":"رضوى عاشور","en":"Radwa Ashour"},"year":1994,"said":{"ar":"تنقلك إلى الأندلس الساقطة، وألهمت جيلًا من الرواية التاريخية.","en":"It carries you into fallen Andalusia and inspired a generation of historical fiction."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"مدام بوفاري","en":"Madame Bovary"},"by":{"ar":"جوستاف فلوبير","en":"Gustave Flaubert"},"year":1857,"said":{"ar":"أبهرته في شبابه بتصويرها النفسي للبطلة، وحاول أن يكتب مثل فلوبير وفشل.","en":"It dazzled him in his youth with its psychological portrait; he tried to write like Flaubert and failed."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"القمر وستة بنسات","en":"The Moon and Sixpence"},"by":{"ar":"سومرست موم","en":"W. Somerset Maugham"},"year":1919,"said":{"ar":"ممتعة للغاية وشبه ملحمية، عن محاسب يترك حياته ليرسم في تاهيتي.","en":"Hugely entertaining and almost epic — the clerk who drops everything to paint in Tahiti."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"book","title":{"ar":"المسيح يصلب من جديد","en":"Christ Recrucified (The Greek Passion)"},"by":{"ar":"نيكوس كازانتزاكيس","en":"Nikos Kazantzakis"},"year":1948,"said":{"ar":"رواية كثيفة لا تُنسى.","en":"A dense, unforgettable novel."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"other","title":{"ar":"سلسلة «أولادنا»","en":"Dar al-Maaref's 'Awladuna' series"},"by":null,"year":null,"said":{"ar":"عرّفته بـ«جزيرة الكنز» و«مونفليت» و«آلة الزمن» وغيرها، وأدفأت جيلًا كاملًا.","en":"It introduced him to Treasure Island, Moonfleet, The Time Machine and more, and warmed a whole generation."},"post":"7580487836260040948","source":"https://aktowfik.blogspot.com/2016/10/2.html"},{"kind":"writer","title":{"ar":"جوزيه ساراماجو","en":"José Saramago"},"by":null,"year":null,"said":{"ar":"سماه «الأديب العظيم»، وأُعجب بسخرية «البصيرة» وفرح لأن فكرة روايته اقتربت من «الطوف الحجري».","en":"He called him 'this great writer', admired the satire of Seeing, and was glad his own idea came close to The Stone Raft."},"post":"4067535336538242235","source":"https://aktowfik.blogspot.com/2011/10/blog-post_10.html"},{"kind":"writer","title":{"ar":"عزيز نيسين","en":"Aziz Nesin"},"by":null,"year":null,"said":{"ar":"الأديب التركي «الرائع» الذي رأى أنه يكتب عن مصر أكثر مما يكتب عن تركيا.","en":"The 'wonderful' Turkish satirist who, he felt, was really writing about Egypt."},"post":"3007787008187835519","source":"https://aktowfik.blogspot.com/2010/07/blog-post_06.html"},{"kind":"book","title":{"ar":"بيت في الدنيا وبيت في الحنين","en":"A House in the World and a House in Longing"},"by":{"ar":"إبراهيم الكوني","en":"Ibrahim al-Koni"},"year":null,"said":{"ar":"سماها ملحمة، وقال إن الكوني «أديب مهم فعلًا وله عالم شديد الثراء والتفرد».","en":"He called it an epic and al-Koni a truly important writer with a rich, unique world."},"post":"4810671056694157213","source":"https://aktowfik.blogspot.com/2007/02/blog-post.html"},{"kind":"book","title":{"ar":"قناع الموت الأحمر","en":"The Masque of the Red Death"},"by":{"ar":"إدجار آلان بو","en":"Edgar Allan Poe"},"year":1842,"said":{"ar":"من كلاسيكيات الأدب العالمي وأدق نموذج للرعب القوطي، لا يتخيله إلا عقل عبقري.","en":"A world classic and the purest example of Gothic horror, imaginable only by a genius."},"post":"2586648679223311039","source":"https://aktowfik.blogspot.com/2017/09/blog-post.html"},{"kind":"book","title":{"ar":"شخصية مصر","en":"The Personality of Egypt"},"by":{"ar":"جمال حمدان","en":"Gamal Hamdan"},"year":null,"said":{"ar":"كتاب صغير رشيق قرأه مبكرًا، يحمل قدرًا هائلًا من الجهد والجدية، وسمّى صاحبه «عبقري في مصر».","en":"A small, elegant book he met young, full of effort and seriousness; he called its author 'a genius in Egypt'."},"post":"415596431333853349","source":"https://aktowfik.blogspot.com/2018/02/blog-post_10.html"},{"kind":"book","title":{"ar":"رحيق العمر","en":"Rahiq al-Umr"},"by":{"ar":"جلال أمين","en":"Galal Amin"},"year":2010,"said":{"ar":"«درة جديرة بأن تُقرأ»، أعجبته صراحتها وبناؤها غير المألوف.","en":"'A gem worth reading' — he praised its frankness and unusual structure."},"post":"3747681047566908249","source":"https://aktowfik.blogspot.com/2010/02/blog-post_24.html"},{"kind":"book","title":{"ar":"كان صبيًا في السبعينيات","en":"He Was a Boy in the Seventies"},"by":{"ar":"محمود عبد الشكور","en":"Mahmoud Abdel Shakour"},"year":null,"said":{"ar":"أحب الكتاب كثيرًا لأنه كان هو أيضًا صبيًا في السبعينيات.","en":"He loved it very much — he too had been a boy in the seventies."},"post":"5272186971730117760","source":"https://aktowfik.blogspot.com/2016/04/blog-post_67.html"},{"kind":"book","title":{"ar":"المغامرون الخمسة","en":"The Five Adventurers"},"by":{"ar":"محمود سالم","en":"Mahmoud Salem"},"year":null,"said":{"ar":"سلسلة ممتعة «أبدعتها عبقرية محمود سالم»، تابع فيها تختخ تلميذًا في الإعدادية.","en":"A delightful series 'created by the genius of Mahmoud Salem' that he followed as a schoolboy."},"post":"4940629198902647210","source":"https://aktowfik.blogspot.com/2010/09/blog-post_29.html"},{"kind":"other","title":{"ar":"تان تان","en":"Tintin"},"by":{"ar":"هيرجيه","en":"Hergé"},"year":null,"said":{"ar":"قال إنه «جزء حقيقي بالغ الأهمية من ذاتي»، وما زال يحتفظ بكل أعداده.","en":"He called it a truly vital part of himself and still kept every issue."},"post":"8948120280206707948","source":"https://aktowfik.blogspot.com/2023/04/blog-post.html"},{"kind":"other","title":{"ar":"مجلة سمير (عصرها الذهبي)","en":"Samir magazine (its golden age)"},"by":null,"year":null,"said":{"ar":"أعجبه أن فنانيها كانوا يحبون ما يفعلونه فعلًا وصنعوا أسلوبًا خاصًا بعيدًا عن التقليد.","en":"He admired that its artists truly loved their work and built a style of their own."},"post":"2485621767829887088","source":"https://aktowfik.blogspot.com/2010/01/blog-post_29.html"},{"kind":"other","title":{"ar":"كاريكاتير مصطفى حسين","en":"Mostafa Hussein's cartoons"},"by":{"ar":"مصطفى حسين","en":"Mostafa Hussein"},"year":null,"said":{"ar":"رحلة حب طويلة مع خطوطه منذ طفولته، وسمّاها «موهبة مذهلة».","en":"A lifelong love of his line since childhood — 'an amazing talent'."},"post":"7407275423388885946","source":"https://aktowfik.blogspot.com/2014/08/blog-post_28.html"},{"kind":"writer","title":{"ar":"بيرم التونسي","en":"Bayram al-Tunisi"},"by":null,"year":null,"said":{"ar":"«عمنا وتاج راسنا وأعظم فنانينا»، بعين حساسة ساخرة ما زالت أبياته تنطبق على اليوم.","en":"'Our uncle, the crown on our heads and our greatest artist', whose verses still fit today."},"post":"4623244713135040727","source":"https://aktowfik.blogspot.com/2009/08/blog-post.html"},{"kind":"writer","title":{"ar":"صلاح جاهين","en":"Salah Jahin"},"by":null,"year":null,"said":{"ar":"يسميه «الشاعر العظيم» ويستشهد بفوازير «الخاطبة».","en":"He calls him 'the great poet' and quotes his Al-Khatba riddles."},"post":"87429429657316372","source":"https://aktowfik.blogspot.com/2014/01/blog-post_28.html"},{"kind":"writer","title":{"ar":"عبد الرحمن الأبنودي","en":"Abdel Rahman El-Abnoudi"},"by":null,"year":null,"said":{"ar":"رثاه بأنه «جزء من نسيج حياتنا والهواء الذي نتنفسه».","en":"He mourned him as part of the fabric of our lives and the air we breathe."},"post":"9009797136906452940","source":"https://aktowfik.blogspot.com/2015/04/blog-post_30.html"},{"kind":"music","title":{"ar":"زهرة المدائن (لأجلك يا مدينة الصلاة)","en":"Zahrat al-Madaen"},"by":{"ar":"فيروز","en":"Fairuz"},"year":1967,"said":{"ar":"سمعها تلميذًا في السبعينيات فأبكته، وطلب من قرائه الاستماع إليها مع المقال.","en":"She made him cry as a schoolboy in the seventies; he asked readers to play it while reading."},"post":"5442812717040122944","source":"https://aktowfik.blogspot.com/2015/10/blog-post_18.html"},{"kind":"film","title":{"ar":"المواطن كين","en":"Citizen Kane"},"by":{"ar":"أورسون ويلز","en":"Orson Welles"},"year":1941,"said":{"ar":"«تحفة أورسون ويلز» وقصتها المؤثرة عن «روزباد».","en":"'Orson Welles's masterpiece' and its moving Rosebud story."},"post":"1042801910774120853","source":"https://aktowfik.blogspot.com/2010/10/blog-post_31.html"},{"kind":"film","title":{"ar":"سفر الرؤيا الآن","en":"Apocalypse Now"},"by":{"ar":"فرانسيس فورد كوبولا","en":"Francis Ford Coppola"},"year":1979,"said":{"ar":"تحفة ظلت مشاهدها تلاحقه، ومارلون براندو أدى دوره «بامتياز».","en":"A masterpiece whose scenes haunted him; Brando played his part superbly."},"post":"1629099072177474895","source":"https://aktowfik.blogspot.com/2014/10/blog-post_63.html"},{"kind":"film","title":{"ar":"دكتور سترينجلوف","en":"Dr. Strangelove"},"by":{"ar":"ستانلي كوبريك","en":"Stanley Kubrick"},"year":1964,"said":{"ar":"مشهد الطيار الممتطي للقنبلة «يلخص العسكرية الأمريكية ببلاغة».","en":"The bomb-riding finale 'eloquently sums up American militarism'."},"post":"2296881967953815321","source":"https://aktowfik.blogspot.com/2014/10/blog-post_12.html"},{"kind":"film","title":{"ar":"مفقود","en":"Missing"},"by":{"ar":"كوستا جافراس","en":"Costa-Gavras"},"year":1982,"said":{"ar":"«هذا الفيلم الرائع» عن صحفي أمريكي اختفى في انقلاب تشيلي.","en":"'This wonderful film' about an American journalist who vanished in Chile's coup."},"post":"4551775308863126111","source":"https://aktowfik.blogspot.com/2016/04/blog-post_0.html"},{"kind":"film","title":{"ar":"أماديوس","en":"Amadeus"},"by":{"ar":"ميلوش فورمان","en":"Miloš Forman"},"year":1984,"said":{"ar":"أوصى بمشاهدته، ورأى سالييري فيه محبًا صادقًا للفن رغم غيرته.","en":"He urged readers to watch it and saw its Salieri as a sincere lover of art despite his envy."},"post":"7108067586238926893","source":"https://aktowfik.blogspot.com/2016/09/blog-post_12.html"},{"kind":"film","title":{"ar":"يوم طفت الأسماك ميتة","en":"The Day the Fish Came Out"},"by":{"ar":"مايكل كاكويانيس","en":"Michael Cacoyannis"},"year":1967,"said":{"ar":"من صنع «عبقري السينما اليونانية»، بنظرة حادة إلى قلق الحرب النووية وموسيقى ثيودوراكيس.","en":"By 'the genius of Greek cinema' — a sharp take on nuclear dread, with Theodorakis's music."},"post":"3492198745992612059","source":"https://aktowfik.blogspot.com/2015/12/blog-post_25.html"},{"kind":"film","title":{"ar":"سينما باراديسو","en":"Cinema Paradiso"},"by":{"ar":"جوزيبي تورناتوري","en":"Giuseppe Tornatore"},"year":1988,"said":{"ar":"رأى فيه العشق المهووس للسينما الذي عاشه هو طفلًا.","en":"He saw in it the obsessive childhood love of cinema he had lived himself."},"post":"5659497887479625762","source":"https://aktowfik.blogspot.com/2021/03/blog-post.html"},{"kind":"film","title":{"ar":"جرايندهاوس","en":"Grindhouse"},"by":{"ar":"كوينتن تارانتينو وروبرت رودريجيز","en":"Quentin Tarantino & Robert Rodriguez"},"year":2007,"said":{"ar":"أعجبه كتحية لأفلام السبعينيات بخدوش الشريط وإعلاناته الزائفة.","en":"He admired it as a tribute to 1970s exploitation films, scratches and fake trailers included."},"post":"5659497887479625762","source":"https://aktowfik.blogspot.com/2021/03/blog-post.html"},{"kind":"film","title":{"ar":"دراكيولا (أفلام هامر، كريستوفر لي)","en":"Dracula — Hammer films with Christopher Lee"},"by":{"ar":"تيرينس فيشر","en":"Terence Fisher"},"year":1958,"said":{"ar":"سحرته أفلام هامر طفلًا، وكان دراكيولا كريستوفر لي مرعبًا.","en":"Hammer horror spellbound him as a child; Christopher Lee's Dracula was terrifying."},"post":"5659497887479625762","source":"https://aktowfik.blogspot.com/2021/03/blog-post.html"},{"kind":"other","title":{"ar":"سامي السلاموني","en":"Sami El-Salamouni (film critic)"},"by":null,"year":null,"said":{"ar":"«كان طفلًا مندهشًا يعشق السينما بجنون»، وكتاباته تستحق أن تُجمع في كتاب.","en":"'A wide-eyed child madly in love with cinema' whose articles deserve a book."},"post":"6944396326437494134","source":"https://aktowfik.blogspot.com/2010/08/blog-post_5530.html"},{"kind":"other","title":{"ar":"مارا/صاد","en":"Marat/Sade"},"by":{"ar":"بيتر فايس","en":"Peter Weiss"},"year":1963,"said":{"ar":"مسرحية فرق الكلية، قال إن «النص ما زال في غاية القوة» ونصح بقراءته.","en":"A college-theatre favourite whose text, he said, is still extremely powerful — read it."},"post":"8594911836508637055","source":"https://aktowfik.blogspot.com/2013/12/blog-post_5.html"},{"kind":"book","title":{"ar":"بلد العميان","en":"The Country of the Blind"},"by":{"ar":"هـ. ج. ويلز","en":"H. G. Wells"},"year":1904,"said":{"ar":"«قصة قصيرة رائعة» لرائد الخيال العلمي، تذكّرها وهو يرفض الرشاوى طبيبًا في الريف.","en":"A 'wonderful short story' he recalled while refusing bribes as a rural doctor."},"post":"4197653838619665368","source":"https://aktowfik.blogspot.com/2011/01/blog-post.html"},{"kind":"book","title":{"ar":"إذا","en":"If—"},"by":{"ar":"روديارد كبلنج","en":"Rudyard Kipling"},"year":1910,"said":{"ar":"من أجمل ما قرأ، رغم نقده لكبلنج بوصفه بوق الإمبراطورية.","en":"Among the most beautiful things he had read, though he faulted Kipling as the Empire's trumpet."},"post":"4197653838619665368","source":"https://aktowfik.blogspot.com/2011/01/blog-post.html"},{"kind":"book","title":{"ar":"النطاق السام","en":"The Poison Belt"},"by":{"ar":"آرثر كونان دويل","en":"Arthur Conan Doyle"},"year":1913,"said":{"ar":"«رواية ممتعة» اتخذها مجازًا لمصر التي تعبر نطاقًا سامًا.","en":"'An enjoyable novel' he used as a metaphor for Egypt passing through a toxic zone."},"post":"3472772353612461876","source":"https://aktowfik.blogspot.com/2015/02/blog-post.html"},{"kind":"book","title":{"ar":"السيدة أم النمر؟","en":"The Lady, or the Tiger?"},"by":{"ar":"فرانك ستوكتون","en":"Frank R. Stockton"},"year":1882,"said":{"ar":"قصة شهيرة شحذت ذكاء القراء وصار عنوانها مثلًا للمعضلة بلا حل.","en":"A famous story that sharpened readers' wits; its title became shorthand for an insoluble dilemma."},"post":"434815869563967333","source":"https://aktowfik.blogspot.com/2014/10/blog-post_14.html"},{"kind":"writer","title":{"ar":"بلال فضل","en":"Belal Fadl"},"by":null,"year":null,"said":{"ar":"«أحببت كتابات بلال فضل كثيرًا» واعتبره من أفضل الأقلام التي قرأها.","en":"He loved Belal Fadl's writing and counted him among the best pens he had read."},"post":"2111357844574046554","source":"https://aktowfik.blogspot.com/2016/05/blog-post.html"},{"kind":"book","title":{"ar":"هاري بوتر","en":"Harry Potter"},"by":{"ar":"ج. ك. رولينج","en":"J. K. Rowling"},"year":null,"said":{"ar":"قرأ السلسلة «واستمتعت بها جدًا»، وإن شك في نجاحها عربيًا.","en":"He read the series and enjoyed it greatly, though he doubted it would catch on in Arabic."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"العنكبوت","en":"The Spider"},"by":{"ar":"مصطفى محمود","en":"Mustafa Mahmoud"},"year":1965,"said":{"ar":"يعتبرها «مرعبة في مواضع كثيرة»، من النماذج النادرة للرعب العربي.","en":"He found it frightening in many places — a rare Arabic horror novel."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"وردة","en":"Warda"},"by":{"ar":"صنع الله إبراهيم","en":"Sonallah Ibrahim"},"year":2000,"said":{"ar":"قال إنها خرجت «رائعة» برغم ما فيها من جرأة.","en":"He said it came out wonderful despite its frank content."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"},{"kind":"book","title":{"ar":"عمارة يعقوبيان","en":"The Yacoubian Building"},"by":{"ar":"علاء الأسواني","en":"Alaa Al Aswany"},"year":2002,"said":{"ar":"قرنها بـ«وردة» روايةً رائعة برغم جرأتها.","en":"He paired it with Warda as a wonderful novel despite its frankness."},"post":null,"source":"https://diwanalarab.com/%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-534.html"}];
window.AKT.refaatLife = [{"when":{"ar":"1924","en":"1924"},"title":{"ar":"المولد في كفر بدر","en":"Born in Kafr Badr"},"text":{"ar":"وُلد رفعت إسماعيل عام 1924 في قرية كفر بدر بمحافظة الشرقية، وأمضى فيها جزءًا من طفولته.","en":"Refaat Ismail was born in 1924 in the village of Kafr Badr, Sharqia Governorate, and spent part of his childhood there."},"issue":null,"source":"https://www.albawabhnews.com/5019717"},{"when":{"ar":"الطفولة","en":"Childhood"},"title":{"ar":"يتيم في بيت خاله بالمنصورة","en":"An orphan in his uncle's house in Mansoura"},"text":{"ar":"بعد وفاة أبيه أخذه خاله ليعيش مع أسرته في المنصورة، فتربى مع أبناء خاله: التوأم عماد ومدحت وأختهما عبير.","en":"After his father died, his maternal uncle took him to live with his family in Mansoura, where he grew up with his cousins, the twins Emad and Medhat and their sister Abeer."},"issue":null,"source":"https://www.albawabhnews.com/5019717"},{"when":{"ar":"الطفولة","en":"Childhood"},"title":{"ar":"طفل عصبي عليل","en":"A nervous, sickly child"},"text":{"ar":"منذ طفولته عُرف بالعصبية والعناد والنحول واعتلال الصحة.","en":"Since childhood he was known for being nervous, stubborn, thin and in poor health."},"issue":null,"source":"https://www.albawabhnews.com/5019717"},{"when":{"ar":"الطفولة","en":"Childhood"},"title":{"ar":"البيت الذي لعب معهم","en":"The house that played with them"},"text":{"ar":"كانت أولى خبراته الخارقة مع أبناء خاله وصديقة طفولتهم إلهام: بيت في المنصورة له قوى خارقة استحوذ عليهم، وصنع لهم وهمًا في صورة فتاة صغيرة تُدعى شيراز. وبعد سنين طويلة عاد البيت يطاردهم فأحرقه رفعت وابنا خاله.","en":"His earliest brush with the supernatural came with his cousins and their childhood friend Elham: a house in Mansoura with uncanny powers possessed them and conjured an illusion of a little girl called Shiraz. Many years later, when the house came after them again, Refaat and his two cousins burned it down."},"issue":"mwt-12","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"الطفولة","en":"Childhood"},"title":{"ar":"إلهام، حب الصغر","en":"Elham, his childhood love"},"text":{"ar":"إلهام السويفي صديقة رفعت منذ أيام الطفولة، وكان يحبها وهو صغير.","en":"Elham El-Sweify was Refaat's friend from childhood days, and he loved her as a boy."},"issue":null,"source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"سنوات الدكتوراه","en":"His doctoral years"},"title":{"ar":"داندي وماجي","en":"Dundee, and Maggie"},"text":{"ar":"درس الدكتوراه في جامعة داندي بإسكتلندا تحت إشراف السير جيمس ماكيلوب، وهناك عرف ابنته ماجي، خبيرة الفيزياء التي صارت حبه الأبدي.","en":"He did his doctorate at the University of Dundee in Scotland under Sir James McKillop, and there he met McKillop's daughter Maggie, a physicist who became the eternal love of his life."},"issue":null,"source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"المهنة","en":"Career"},"title":{"ar":"أستاذ أمراض الدم","en":"Professor of haematology"},"text":{"ar":"صار طبيب أمراض دم، ويقدّم نفسه بأنه «أستاذ الدم المتقاعد» الذي قضى حياته صائدًا للأشباح ولم يتزوج قط.","en":"He became a haematologist, and introduces himself as a \"retired professor of blood\" who spent his life hunting ghosts and never married."},"issue":"mwt-45","source":"https://www.abjjad.com/book/2793570312/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A8%D9%8A%D8%AA-%D8%A7%D9%84%D8%A7%D9%81%D8%A7%D8%B9%D9%8A-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-45/2794618888"},{"when":{"ar":"1959","en":"1959"},"title":{"ar":"مومياء دراكيولا","en":"Dracula's mummy"},"text":{"ar":"يعدّ رفعت أولى خبراته المسجلة مع الخوارق عام 1959، حين شهد محاولة طبيبين، ريتشارد كامنجز ولوفاريسكي، لإعادة إحياء مومياء الكونت دراكيولا، وانتهت التجربة بفراره.","en":"Refaat counts 1959 as his first recorded supernatural experience: he witnessed two doctors, Richard Cummings and Lovarisky, try to revive the mummy of Count Dracula, and the experiment ended with him running away."},"issue":"mwt-1","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"1961","en":"1961"},"title":{"ar":"المذءوب في رومانيا","en":"The werewolf in Romania"},"text":{"ar":"في 1961 واجه مستذئبًا في رومانيا واكتشف أنه خدعة، وفيها عرف صديقه الحميم الروماني جوستاف فيكولسو.","en":"In 1961 he faced a werewolf in Romania and found it was a hoax; there he met his close Romanian friend Gustav Vikolso."},"issue":"mwt-1","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"النداهة تنادي رضا","en":"The Naddaha calls Reda"},"text":{"ar":"عاد إلى كفر بدر فاستقبلته أمه وأخته رئيفة، وعرف أن أخاه رضا لبّى نداء النداهة. ثم نادته النداهة هو فمنعه طلعت زوج رئيفة، إلى أن كشف تحليل دم رضا أثرًا من الباربيتورات وانكشف من وراء اللعبة.","en":"Back in Kafr Badr, his mother and his sister Raeefa welcomed him, and he learned that his brother Reda had answered the Naddaha's call. Then the Naddaha called Refaat himself and Raeefa's husband Talaat held him back, until a test of Reda's blood showed traces of barbiturates and the people behind the hoax were exposed."},"issue":"mwt-2","source":"https://ar.wikipedia.org/wiki/أسطورة_النداهة_(رواية)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"رضا ونجاة ورئيفة وطلعت","en":"Reda, Nagat, Raeefa and Talaat"},"text":{"ar":"لم يبق من أسرته سوى أخيه رضا، الذي تكرهه زوجته نجاة كثيرًا، وأخته رئيفة التي يزورها من حين لآخر ويحتفظ بعلاقة طيبة مع زوجها طلعت.","en":"Of his family only his brother Reda, whose wife Nagat greatly dislikes Refaat, and his sister Raeefa remain; he visits her now and then and gets on well with her husband Talaat."},"issue":null,"source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"وحش لوخ نس","en":"The Loch Ness monster"},"text":{"ar":"في أول ظهور لماجي وأبيها، شارك في تجربة السير ماكيلوب لحمل وحش لوخ نس على إظهار نفسه، فظهر، وأنقذ رفعت ماجي من الوحش الذي كان سيأخذها قربانًا. اهتز منطقه العلمي لأول مرة.","en":"In Maggie and her father's first appearance, he joined Sir McKillop's experiment to lure the Loch Ness monster into showing itself. It did, and Refaat saved Maggie from the creature that was about to take her as an offering; for the first time his scientific reasoning was shaken."},"issue":"mwt-3","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"عزت، الجار «آكل البشر»","en":"Ezzat, the 'cannibal' next door"},"text":{"ar":"ظن أن جاره في الشقة المقابلة، المثّال المريض عزت، آكل لحوم بشر، وشاركه الظن صديق طفولته عادل، ثم اتضح أنه سوء تفاهم: أساء رفعت تفسير مرض جاره وهوايته في نحت التماثيل.","en":"He believed his neighbour across the landing, the sickly sculptor Ezzat, was a cannibal, and his childhood friend Adel shared the belief, until it turned out to be a misunderstanding: Refaat had misread his neighbour's illness and his hobby of sculpting."},"issue":"mwt-4","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"عادل وشاهين","en":"Adel and Shaheen"},"text":{"ar":"ظهر في العدد نفسه صديق طفولته عادل توفيق، العميد في مديرية أمن الإسكندرية، والأنثروبولوجي د. محمد شاهين الذي ظن رفعت نفسه آكل بشر ثم صار صديقه.","en":"The same issue introduced his childhood friend Adel Tawfik, a brigadier in the Alexandria security directorate, and the anthropologist Dr. Mohamed Shaheen, who suspected Refaat himself of cannibalism and then became his friend."},"issue":"mwt-4","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"زومبي جمايكا","en":"The zombies of Jamaica"},"text":{"ar":"في إجازة بجمايكا مع صديقه الأمريكي هاري شيلدون وزوجته ليندا وطفلهما جيمي، فضح طبيبًا فرنسيًا يدير مستعمرة للجذام ويستخدم أسطورة الزومبي غطاءً لتجارته. التغطية الصحفية لهذه المغامرة جعلته مشهورًا كهاوٍ لعالم الخوارق.","en":"On holiday in Jamaica with his American friend Harry Sheldon, Harry's wife Linda and their son Jimmy, he exposed a French doctor who ran a leper colony and used the zombie legend to hide his trade. Press coverage of this adventure made him famous as an amateur of the supernatural."},"issue":"mwt-5","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"خطيبته هويدا ولعنة الفرعون","en":"His fiancée Huwaida and the Pharaoh's curse"},"text":{"ar":"استعانت به هيئة الآثار في لعنة غامضة تخص فرعونًا سمّوه «أخيروم»، ولما حاول تشريح موميائه طارد حارسُ الفرعون خطيبته هويدا وكاد يفتك بها.","en":"The Antiquities Authority called him in over a mysterious curse tied to a pharaoh they called \"Akhirom\"; when he tried to dissect the mummy, the pharaoh's guardian hunted his fiancée Huwaida and nearly killed her."},"issue":"mwt-9","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"الخطبة التي فشلت","en":"The engagement that failed"},"text":{"ar":"حاول عادل وزوجته سهام تزويجه من هويدا أخت سهام، لكن المحاولة فشلت بسبب ما يسميه رفعت «إرادة النكد»، ولا يحسم أبدًا هل أحبها أم لا.","en":"Adel and his wife Siham tried to marry him to Siham's sister Huwaida, but it failed through what Refaat calls \"the will of misery\"; he never settles whether he loved her."},"issue":null,"source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"حلقة الرعب الأولى","en":"The first Horror Circle"},"text":{"ar":"في فيلا المحلل النفسي د. سامي فهيم حكى قصة صديقه يوسف، وجلس معهم شبح شاكر بك متقمصًا صورة رفيقهم شكري، ولم يعرفوا إلا حين اتصل شكري يعتذر عن غيابه.","en":"At the villa of the psychoanalyst Dr. Sami Fahim he told the story of his friend Youssef, while the ghost of Shaker Bey sat among them in the shape of their friend Shoukry; they realised only when Shoukry phoned to apologise for not coming."},"issue":"mwt-10","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"الكاهن الأخير يصل إلى كفر بدر","en":"The last priest reaches Kafr Badr"},"text":{"ar":"هن-تشو-كان، آخر كهنة النافاراي، قفز بكتاب الشوكارا من التبت في القرن السادس عشر إلى كفر بدر في القرن العشرين، فاصطحبه رفعت إلى شقته وآواه وصار صديقه.","en":"Hen-Tcho-Kan, the last of the Navarai priests, leapt with the Shokara book from 16th-century Tibet to 20th-century Kafr Badr; Refaat took him home to his flat, sheltered him and became his friend."},"issue":"mwt-11","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"موت أمه","en":"His mother's death"},"text":{"ar":"توفيت أمه أثناء معاناته من مطاردة نبات «الموكاسا نيجرا» القاتل له، وظل يذكرها بعد ذلك دائمًا.","en":"His mother died while he was being hunted by the killer plant Mukasa Nigra, and he kept remembering her ever after."},"issue":"mwt-15","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"سام كولبي وإدجار آلان بو","en":"Sam Colby and Edgar Allan Poe"},"text":{"ar":"حاول النصاب الأمريكي سام كولبي إقناعه بأنه تجسد للشاعر إدجار آلان بو، فعرّضه لتجربة خارقة ألقته في عوالم بو الكابوسية.","en":"The American con man Sam Colby tried to convince him that he was the reincarnation of Edgar Allan Poe, and dragged him into an uncanny experience inside Poe's nightmare worlds."},"issue":"mwt-19","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"1968","en":"1968"},"title":{"ar":"لقاء لوسيفر","en":"Meeting Lucifer"},"text":{"ar":"في حفل لرابطة سحرة نيويورك دعاه إليه كولبي، قابل د. فرانتز لوسيفر، قارئ التاروت «المجري» الذي يوحي بأنه تجسيد للشيطان، وتنبأ للحاضرين بنهايات مرعبة.","en":"At a party of the New York witches' society, where Colby had invited him, he met Dr. Franz Lucifer, the \"Hungarian\" tarot reader who hints that he is the devil incarnate, and who foretold dreadful ends for those present."},"issue":"mwt-20","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"شعب الأطياف وكاميليا","en":"The spectres, and Camilia"},"text":{"ar":"تحقق من نبوءة لوسيفر بأنه سيموت على يد مخلوقين غير أرضيين، فاكتشف شعب الأطياف. وفيها قابل أستاذة الفلسفة د. كاميليا، ليتبين أنها طيف متنكر في صورتها، ثم صادق كاميليا الحقيقية لاحقًا.","en":"Checking Lucifer's prophecy that he would die at the hands of two unearthly beings, he discovered the people of the spectres. Here he met the philosophy professor Dr. Camilia, only to learn it was a spectre wearing her face; later he befriended the real Camilia."},"issue":"mwt-21","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"1969–1970","en":"1969–1970"},"title":{"ar":"على الهواء «بعد منتصف الليل»","en":"On air: \"After Midnight\""},"text":{"ar":"كان ضيفًا دائمًا على برنامج «بعد منتصف الليل» الذي يقدمه المذيع شريف السعدني ويتلقى فيه اتصالات المستمعين عن الخوارق، ثم منعته الرقابة لأثره على نفسية الأطفال.","en":"He was a regular guest on the programme \"After Midnight\", hosted by Sherif El-Saadany, which took listeners' calls about the paranormal, until the censors banned it for its effect on children."},"issue":"mwt-30","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"رفعت الآخر","en":"The other Refaat"},"text":{"ar":"اتصل به شخص يعرّف نفسه بأنه د. رفعت إسماعيل، فإذا هو رفعت من عالم موازٍ جاء ليتبادل معه المكان، فأعاده رفعت إلى عالمه بالحيلة.","en":"A man phoned calling himself Dr. Refaat Ismail: it was Refaat from a parallel world who had come to swap places with him, and Refaat tricked him back into his own world."},"issue":"mwt-32","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"الشاحبون في هالماجيو","en":"The Pale Ones of Halmageu"},"text":{"ar":"في قرية هالماجيو برومانيا، التي تحولت إلى مجتمع يُعَدّ لعودة فلاد الوالاشي، أنقذه لوسيفر هو وجوستاف من الشاحبين، ومنع رفعت فلاد من عبور البوابة.","en":"In the Romanian village of Halmageu, turned into a community preparing for the return of Vlad of Wallachia, Lucifer saved him and Gustav from the Pale Ones, and Refaat stopped Vlad from crossing the gate."},"issue":"mwt-34","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"رفعت الرضيع","en":"Refaat the infant"},"text":{"ar":"تحوّل رفعت إلى طفل رضيع، فاعتنت به د. كاميليا.","en":"Refaat was turned into a baby, and Dr. Camilia took care of him."},"issue":"mwt-43","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"محاكمة جانب النجوم","en":"On trial on the Side of the Stars"},"text":{"ar":"خدعه لوسيفر فنقله إلى جانب النجوم، حيث يتنافس الخطاة على رواية آثامهم، فلم يجد رفعت ما يحكيه سوى سرقة المربى والكذب بشأن الاستحمام في طفولته، فأطلق لوسيفر سراحه.","en":"Lucifer tricked him onto the Side of the Stars, where sinners compete in telling their worst sins; Refaat could only confess to stealing jam and lying about his baths as a child, and Lucifer let him go."},"issue":"mwt-50","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"زواجه من رونيل السوداء","en":"His marriage to Black Ronel"},"text":{"ar":"تحت تأثير وصفة حب سحرية تزوج الساحرة رونيل السوداء التي احتلت جسد الطفلة إليانور، وأنجب منها طفلًا اسمه سمير نما بسرعة غير طبيعية. أنقذته ماجي، واختفى سمير بعد احتراق رونيل، وأقنعته ماجي بأنه لم يتزوج ولم ينجب.","en":"Under a magic love potion he married the witch Black Ronel, who had taken over the body of the girl Eleanor, and had a son by her, Samir, who grew unnaturally fast. Maggie saved him, Samir vanished when Ronel burned, and Maggie convinced him that he had never married or fathered a child."},"issue":"mwt-59","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"نادي الغيلان","en":"The Ghouls' Club"},"text":{"ar":"تحول صديقه د. سامي فهيم إلى غول آدمي، فتدخل رفعت لحل نادي الغيلان ومعاونة سامي على الشفاء. وكان هذا آخر ظهور لعادل توفيق.","en":"His friend Dr. Sami Fahim turned into a human ghoul, and Refaat stepped in to break up the Ghouls' Club and help Sami recover. It was Adel Tawfik's last appearance."},"issue":"mwt-69","source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"آخر ظهور لماجي","en":"Maggie's last appearance"},"text":{"ar":"في مرتفعات إسكتلندا مع ماجي كان آخر ظهور لها في السلسلة، وفيها أرسل إليه لوسيفر ابنه خرياسوس المدوّن الذي يكتب قصصًا حقيقية.","en":"Maggie's last appearance in the series came in the Scottish Highlands with Refaat; in this issue Lucifer sent him his son, Chryasus the Chronicler, who writes true stories."},"issue":"mwt-73","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"في السبعين","en":"In his seventies"},"title":{"ar":"العجوز الراوي","en":"The old narrator"},"text":{"ar":"يروي رفعت ذكرياته وهو طبيب أعزب في السبعينات، «أفنى سبعين عامًا من عمره تقريبًا» مع قصص الأشباح.","en":"Refaat tells his memories as a bachelor doctor in his seventies, who has \"spent nearly seventy years of his life\" among ghost stories."},"issue":"mwt-25","source":"https://www.abjjad.com/book/2793340938/%D8%A7%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D8%A7%D9%84%D8%AC%D9%86%D8%B1%D8%A7%D9%84-%D8%A7%D9%84%D8%B9%D8%A7%D8%A6%D8%AF-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D9%85%D8%A7-%D9%88%D8%B1%D8%A7%D8%A1-%D8%A7%D9%84%D8%B7%D8%A8%D9%8A%D8%B9%D8%A9-2/2794389514"},{"when":{"ar":"الشيخوخة","en":"Old age"},"title":{"ar":"قلب واهن وعلل كثيرة","en":"A weak heart and many ailments"},"text":{"ar":"يدخن بشراهة، ويحمل دائمًا حبوب النيتروجلسرين لقلبه الواهن، ويعاني الربو وضيق الشرايين التاجية والقرحة.","en":"He smokes heavily, always carries nitroglycerin pills for his weak heart, and suffers from asthma, narrowed coronary arteries and an ulcer."},"issue":null,"source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"الشيخوخة","en":"Old age"},"title":{"ar":"جلطة دماغية","en":"A stroke"},"text":{"ar":"أصيب رفعت بجلطة دماغية، فلجأت إليه أسرة جاره الأستاذ زكريا رغم ظنونه به لأنه أعزب.","en":"Refaat suffered a stroke, and the family of his downstairs neighbour Mr. Zakaria, who had always been suspicious of the bachelor, came to his side."},"issue":null,"source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"ترتيب الأعداد","en":"Issue order"},"title":{"ar":"حامل الضياء","en":"The Light-Bearer"},"text":{"ar":"شعر لوسيفر بدنوّ موت رفعت فقرر إنهاء الصراع بينهما، وراح يفتش في ذكريات أجداده داخل عقله عن كتاب تحوت الذي خبأه جده الأكبر الحكيم سمعان. وفي الجزأين أُعيد إحياء أليستر كراولي، وانتحر كولبي.","en":"Sensing that Refaat's death was near, Lucifer decided to end their long feud and searched the memories of Refaat's ancestors inside his mind for the Book of Thoth, hidden by his forefather the sage Simeon. Aleister Crowley was brought back to life across the two parts, and Colby killed himself."},"issue":"mwt-78","source":"https://ar.wikipedia.org/wiki/رفعت_إسماعيل"},{"when":{"ar":"الأيام الأخيرة","en":"The last days"},"title":{"ar":"السرطان في العظام","en":"Cancer in his bones"},"text":{"ar":"في «أسطورة الأساطير» تعبث خلايا السرطان في عظام العجوز، والوقت لم يعد يسمح بإرجاء الإجابات عن أسئلة السلسلة المعلقة: د. كامنجز، وأطلنطس، وبيت بورلي.","en":"In \"The Legend of Legends\" cancer is spreading through the old man's bones, and there is no time left to put off answering the series' open questions: Dr. Cummings, Atlantis, Borley Rectory."},"issue":"mwt-80","source":"https://www.abjjad.com/book/2196996335/اسطورة-الاساطير-الجزء-الاول-سلسلة-ما-وراء-الط/2197258481"},{"when":{"ar":"8 أغسطس","en":"8 August"},"title":{"ar":"رحيل رفعت إسماعيل","en":"The death of Refaat Ismail"},"text":{"ar":"صباح الثلاثاء 8 أغسطس توقف قلب د. رفعت إسماعيل عن الخفقان، في الجزء الثاني من «أسطورة الأساطير» الذي أنهى السلسلة عام 2014. وما زال قراؤه يحيون ذكراه كل عام في هذا اليوم.","en":"On the morning of Tuesday 8 August Dr. Refaat Ismail's heart stopped, in the second part of \"The Legend of Legends\", which ended the series in 2014. His readers still mark the day every year."},"issue":"mwt-80","source":"https://www.egypttelegraph.com/63739"}];
window.AKT.creatures = [{"id":"werewolf","name":{"ar":"المذءوب","en":"The werewolf"},"kind":"shapeshifter","issues":["mwt-1","mwt-20"],"lore":{"ar":"إنسان يتحول إلى ذئب أو مخلوق نصفه ذئب، غالبًا عند اكتمال البدر، وهو من أقدم أساطير أوروبا.","en":"A person who turns into a wolf or a wolf-like creature, usually under the full moon; one of Europe's oldest legends."},"inBooks":{"ar":"في رومانيا عام 1961 طارد رفعت مذءوبًا تبين أنه خدعة؛ وفي «حكايات التاروت» أقنع لوسيفر سام كولبي بأن أسرة بأكملها مستذئبون.","en":"In Romania in 1961 Refaat hunted a werewolf that proved a hoax; in \"Tarot Tales\" Lucifer convinced Sam Colby that a whole family were werewolves."},"source":"https://en.wikipedia.org/wiki/Werewolf"},{"id":"dracula","name":{"ar":"دراكيولا وفلاد الوالاشي","en":"Dracula / Vlad of Wallachia"},"kind":"vampire","issues":["mwt-1","mwt-34","mwt-35"],"lore":{"ar":"الكونت دراكولا مصاص دماء رواية برام ستوكر (1897)، استُلهم اسمه من فلاد الثالث أمير والاشيا الملقب بالمخوزق.","en":"Count Dracula is the vampire of Bram Stoker's 1897 novel, named after Vlad III, the \"Impaler\" prince of Wallachia."},"inBooks":{"ar":"أول مغامرات رفعت محاولة لإحياء مومياء الكونت دراكيولا عام 1959؛ وفي «الشاحبين» و«دماء دراكيولا» منع فلاد الوالاشي من العودة عبر بوابة هالماجيو.","en":"Refaat's first adventure is an attempt to revive Count Dracula's mummy in 1959; in \"The Pale Ones\" and \"Dracula's Blood\" he stops Vlad of Wallachia returning through the Halmageu gate."},"source":"https://en.wikipedia.org/wiki/Count_Dracula"},{"id":"lilith","name":{"ar":"ليليث","en":"Lilith"},"kind":"vampire","issues":[],"lore":{"ar":"شيطانة في التراث اليهودي، تقول الحكايات إنها زوجة آدم الأولى، وتُصوَّر خاطفة للأطفال ومغوية للرجال.","en":"A female demon of Jewish folklore, said in some tales to be Adam's first wife, pictured as a stealer of babies and seducer of men."},"inBooks":{"ar":"في «أسطورة مصاص الدماء»، إحدى مغامرات رفعت الثلاث المنشورة على موقع «روايتي» خارج السلسلة، يحكي عن مواجهته مصاصة الدماء ليليث.","en":"In \"The Legend of the Vampire\", one of three Refaat stories published outside the series on the Riwayti website, he tells of facing the vampire Lilith."},"source":"https://en.wikipedia.org/wiki/Lilith"},{"id":"naddaha","name":{"ar":"النداهة","en":"The Naddaha"},"kind":"folk","issues":["mwt-2"],"lore":{"ar":"من الفولكلور الريفي المصري: روح أنثوية حسناء تنادي الرجال بأسمائهم ليلًا فتجذبهم إلى النيل والترع، ومن يلحق بها يهلك أو يختفي.","en":"From Egyptian rural folklore: a beautiful female spirit who calls men by name at night and lures them to the Nile and the canals; whoever follows her dies or vanishes."},"inBooks":{"ar":"في كفر بدر لبّى رضا أخو رفعت نداء النداهة ثم نادت رفعت نفسه، قبل أن يكشف تحليل الدم أن وراءها خدعة بشرية.","en":"In Kafr Badr Refaat's brother Reda answered the Naddaha's call, then she called Refaat himself, until a blood test revealed a human hoax behind it."},"source":"https://en.wikipedia.org/wiki/El_Naddaha"},{"id":"loch-ness","name":{"ar":"وحش بحيرة لوخ نس","en":"The Loch Ness Monster"},"kind":"creature","issues":["mwt-3"],"lore":{"ar":"مخلوق يُقال إنه يسكن بحيرة لوخ نس في المرتفعات الإسكتلندية، اشتهر بصورة «الجرّاح» عام 1934 التي ثبت تزويرها.","en":"A creature said to live in Loch Ness in the Scottish Highlands, made famous by the 1934 \"surgeon's photograph\", later shown to be a fake."},"inBooks":{"ar":"يحمل السير ماكيلوب الوحش على الظهور فيظهر فعلًا، وينقذ رفعت ماجي منه قبل أن يأخذها قربانًا.","en":"Sir McKillop lures the monster into showing itself and it does; Refaat saves Maggie before it takes her as an offering."},"source":"https://en.wikipedia.org/wiki/Loch_Ness_Monster"},{"id":"cannibal","name":{"ar":"آكل لحوم البشر","en":"The cannibal"},"kind":"other","issues":["mwt-4"],"lore":{"ar":"أكل البشر لحوم بني جنسهم، عُرف تاريخيًا في طقوس بعض الشعوب وفي المجاعات، وصار من أعمدة أدب الرعب.","en":"Humans eating human flesh, known historically in some peoples' rituals and in famines, and a staple of horror fiction."},"inBooks":{"ar":"يظن رفعت جاره المثّال عزت آكل بشر، ويظن د. شاهين رفعت آكل بشر؛ والحقيقة سوء تفاهم مضحك.","en":"Refaat suspects his neighbour Ezzat, a sculptor, of cannibalism, and Dr. Shaheen suspects Refaat; it is all a comic misunderstanding."},"source":"https://en.wikipedia.org/wiki/Human_cannibalism"},{"id":"ghoul","name":{"ar":"الغول","en":"The ghoul"},"kind":"folk","issues":["mwt-69"],"lore":{"ar":"الغول في التراث العربي كائن يسكن الخرائب والمقابر ويأكل لحوم البشر والموتى، وقد يتشكل في صور مختلفة.","en":"In Arabic folklore the ghoul haunts ruins and graveyards and feeds on human flesh and the dead, often taking other shapes."},"inBooks":{"ar":"صديقه د. سامي فهيم يتحول إلى غول آدمي في «نادي الغيلان»، ويواجه رفعت مع عادل جماعة تريد إحياء الغول الكامن في البشر.","en":"His friend Dr. Sami Fahim becomes a human ghoul in \"The Ghouls' Club\"; Refaat and Adel face a group out to awaken the ghoul that civilisation buried in humans."},"source":"https://en.wikipedia.org/wiki/Ghoul"},{"id":"zombie","name":{"ar":"الزومبي","en":"The zombie"},"kind":"undead","issues":["mwt-5"],"lore":{"ar":"في الفودو الهايتي، الزومبي جثة يعيدها ساحر إلى الحياة ويسخّرها عبدًا بلا إرادة.","en":"In Haitian Vodou a zombie is a corpse raised by a sorcerer and kept as a will-less slave."},"inBooks":{"ar":"في جمايكا يتضح أن «الموتى الأحياء» غطاء لطبيب فرنسي يستغل مرضى الجذام عمالة مجانية.","en":"In Jamaica the \"living dead\" turn out to be a cover for a French doctor exploiting leprosy patients as free labour."},"source":"https://en.wikipedia.org/wiki/Zombie"},{"id":"medusa","name":{"ar":"رأس ميدوسا","en":"Medusa's head"},"kind":"myth","issues":["mwt-6"],"lore":{"ar":"في الأساطير الإغريقية، ميدوسا جورجونة شعرها أفاعٍ وتحيل من ينظر إليها حجرًا، قطع رأسها البطل برسيوس.","en":"In Greek myth Medusa is a Gorgon with snakes for hair whose gaze turns onlookers to stone; the hero Perseus cut off her head."},"inBooks":{"ar":"زميلة دراسته تابيثا ماكجفرت وزوجها اليوناني يحاولان إقناعه بأن رأس ميدوسا موجود، فيكشف الخدعة.","en":"His former classmate Tabitha McGivert and her Greek husband try to convince him that Medusa's head exists; he sees through the trick."},"source":"https://en.wikipedia.org/wiki/Medusa"},{"id":"pharaohs-curse","name":{"ar":"لعنة الفراعنة","en":"The Pharaoh's curse"},"kind":"other","issues":["mwt-9"],"lore":{"ar":"اعتقاد شاع بعد فتح مقبرة توت عنخ آمون عام 1922 بأن من يزعج المومياوات المصرية تصيبه لعنة قاتلة.","en":"A belief that spread after Tutankhamun's tomb was opened in 1922: whoever disturbs an Egyptian mummy is struck by a deadly curse."},"inBooks":{"ar":"يحاول رفعت تشريح مومياء الفرعون «أخيروم»، فيطارد حارس الفرعون خطيبته هويدا.","en":"Refaat tries to dissect the mummy of the pharaoh \"Akhirom\", and the pharaoh's guardian hunts his fiancée Huwaida."},"source":"https://en.wikipedia.org/wiki/Curse_of_the_pharaohs"},{"id":"mummy","name":{"ar":"المومياء","en":"The mummy"},"kind":"undead","issues":["mwt-1","mwt-9","mwt-48"],"lore":{"ar":"الجثث المحنطة التي صارت في أفلام الرعب منذ ثلاثينيات القرن العشرين وحوشًا تعود إلى الحياة.","en":"Embalmed bodies that horror films since the 1930s have turned into monsters that rise again."},"inBooks":{"ar":"من مومياء دراكيولا في العدد الأول إلى «أسطورة المومياء» التي يقول فيها رفعت إن «ليست كل المومياوات لطيفة المعشر».","en":"From Dracula's mummy in the first issue to \"The Legend of the Mummy\", where Refaat warns that \"not all mummies are good company\"."},"source":"https://en.wikipedia.org/wiki/Mummy_(undead)"},{"id":"spontaneous-combustion","name":{"ar":"الاحتراق التلقائي","en":"Spontaneous human combustion"},"kind":"other","issues":["mwt-13"],"lore":{"ar":"ظاهرة مزعومة لاحتراق جسد إنسان دون مصدر نار خارجي ظاهر، يتداولها الناس منذ القرن الثامن عشر.","en":"A claimed phenomenon of a human body burning with no apparent outside source of fire, told since the 18th century."},"inBooks":{"ar":"أناس يحترقون في ثوانٍ فلا يبقى منهم سوى رماد وألسنة من اللهب الأزرق، ورفعت يفتش عن السر.","en":"People burst into flame in seconds, leaving only ash and tongues of blue fire, and Refaat searches for the secret."},"source":"https://en.wikipedia.org/wiki/Spontaneous_human_combustion"},{"id":"yeti","name":{"ar":"رجل الثلوج (الياتي)","en":"The Yeti"},"kind":"creature","issues":["mwt-14"],"lore":{"ar":"مخلوق ضخم يشبه القرد يُقال إنه يعيش في جبال الهيمالايا، ويسمى «رجل الثلوج البغيض».","en":"A large ape-like creature said to live in the Himalayas, also called the Abominable Snowman."},"inBooks":{"ar":"يسمونه «مي جي» بالمنغولية و«ياتي» في التبت، ويواجه رفعت لغز آثار قدميه على الثلج.","en":"Called \"Mi-gyi\" in Mongolian and \"Yeti\" in Tibet; Refaat faces the riddle of its footprints in the snow."},"source":"https://en.wikipedia.org/wiki/Yeti"},{"id":"man-eating-plant","name":{"ar":"النبات القاتل","en":"The killer plant"},"kind":"creature","issues":["mwt-15"],"lore":{"ar":"حكايات «الشجرة آكلة البشر» انتشرت منذ القرن التاسع عشر، أشهرها خدعة شجرة مدغشقر عام 1874.","en":"Tales of the \"man-eating tree\" spread from the 19th century, the best known being the 1874 Madagascar tree hoax."},"inBooks":{"ar":"نبات «الموكاسا نيجرا» يفكر ويتحرك ويقتل، ويطارد رفعت حتى قريته، وفي أثناء ذلك تموت أمه.","en":"The Mukasa Nigra plant thinks, moves and kills; it hunts Refaat as far as his village, and his mother dies meanwhile."},"source":"https://en.wikipedia.org/wiki/Man-eating_tree"},{"id":"minotaur","name":{"ar":"المينوتور","en":"The Minotaur"},"kind":"myth","issues":["mwt-22"],"lore":{"ar":"في الأساطير الإغريقية، مخلوق برأس ثور وجسد إنسان حُبس في متاهة كريت وقتله ثيسيوس.","en":"In Greek myth a creature with a bull's head and a man's body, kept in the Labyrinth of Crete and slain by Theseus."},"inBooks":{"ar":"تصل رفعت رسالة من تابيثا ماكجفرت في اليونان عن المينوتور، وعظام مبعثرة وخطوات في الظلام.","en":"A letter reaches Refaat from Tabitha McGivert in Greece about the Minotaur: scattered bones and footsteps in the dark."},"source":"https://en.wikipedia.org/wiki/Minotaur"},{"id":"esp","name":{"ar":"الإدراك فوق الحسي","en":"Extrasensory perception"},"kind":"other","issues":["mwt-24","mwt-25","mwt-26","mwt-39"],"lore":{"ar":"قدرة مزعومة على تلقي المعلومات بغير الحواس الخمس، كالتخاطر والاستبصار، درسها جوزيف راين في ثلاثينيات القرن العشرين.","en":"A claimed ability to receive information beyond the five senses, such as telepathy and clairvoyance, studied by J. B. Rhine in the 1930s."},"inBooks":{"ar":"البولندي إيجور تاركوفسكي يرسل لرفعت خطابًا طويلًا عن قصته مع الإدراك فوق الحسي يقدمه في ثلاثة كتيبات، ثم يستعين به رفعت في «أسطورة التوءمين».","en":"The Pole Igor Tarkovsky sends Refaat a long letter about his life with ESP, presented over three issues; later Refaat calls on him in \"The Legend of the Twins\"."},"source":"https://en.wikipedia.org/wiki/Extrasensory_perception"},{"id":"jathoom","name":{"ar":"الجاثوم","en":"The Jathoom (sleep paralysis)"},"kind":"demon","issues":["mwt-29"],"lore":{"ar":"في الموروث العربي كائن يجثم على صدر النائم فيشلّه؛ والطب يسمي الحالة «شلل النوم» مع هلاوس مفزعة.","en":"In Arab tradition a being that squats on a sleeper's chest and pins him down; medicine calls it sleep paralysis, with frightening hallucinations."},"inBooks":{"ar":"قصة عن الكوابيس، والبقاء وحيدًا في قصر فسيح مظلم يجول فيه كيان مريع.","en":"A story of nightmares and of being alone in a vast dark palace roamed by a dreadful presence."},"source":"https://en.wikipedia.org/wiki/Sleep_paralysis"},{"id":"doppelganger","name":{"ar":"القرين","en":"The doppelgänger"},"kind":"other","issues":["mwt-32"],"lore":{"ar":"في الفولكلور الأوروبي، القرين نسخة مطابقة من الإنسان، ورؤيتها نذير شؤم.","en":"In European folklore the doppelgänger is a living double of a person, and seeing it is an ill omen."},"inBooks":{"ar":"رفعت إسماعيل آخر من عالم موازٍ يأتي ليحتل مكانه، فيعيده رفعت إلى عالمه بالحيلة.","en":"Another Refaat Ismail from a parallel world comes to take his place, and Refaat tricks him back home."},"source":"https://en.wikipedia.org/wiki/Doppelgänger"},{"id":"voodoo-doll","name":{"ar":"دمية الفودو","en":"The voodoo doll"},"kind":"folk","issues":["mwt-37"],"lore":{"ar":"دمى يُعتقد أن ما يصيبها يصيب الشخص الذي تمثله، وتُنسب شعبيًا إلى الفودو في الكاريبي.","en":"Dolls believed to pass whatever is done to them on to the person they represent, popularly linked to Caribbean Vodou."},"inBooks":{"ar":"ساحرتا الفودو الأم مارشا وماريانا بوجادو تستوليان على الدمية التي تمثل زوجة هاري شيلدون طمعًا في الشباب.","en":"The voodoo witches Mother Marsha and Mariana Bogado seize the doll representing Harry Sheldon's wife, seeking youth."},"source":"https://en.wikipedia.org/wiki/Voodoo_doll"},{"id":"frankenstein","name":{"ar":"مسخ فرانكنشتاين","en":"Frankenstein's monster"},"kind":"creature","issues":["mwt-41"],"lore":{"ar":"مخلوق رواية ماري شيلي (1818): جسد يجمعه العالم فيكتور فرانكنشتاين من أشلاء ويبعث فيه الحياة.","en":"The creature of Mary Shelley's 1818 novel: a body pieced together by the scientist Victor Frankenstein and brought to life."},"inBooks":{"ar":"الصواعق تسري في جهاز فيكتور فرانكنشتاين فيُسمع الأنين من تحت الملاءة، ويذهب رفعت إلى ألمانيا ليتحقق من أمر عالِم.","en":"Lightning runs through Victor Frankenstein's apparatus and a groan rises under the sheet; Refaat travels to Germany to look into a scientist."},"source":"https://en.wikipedia.org/wiki/Frankenstein's_monster"},{"id":"peking-man","name":{"ar":"رجل بكين","en":"Peking Man"},"kind":"other","issues":["mwt-44"],"lore":{"ar":"حفريات بشر منقرضين اكتُشفت قرب بكين في عشرينيات القرن العشرين، وضاعت صناديقها عام 1941 ولم يُعثر عليها حتى اليوم.","en":"Fossils of an extinct human found near Beijing in the 1920s; their crates went missing in 1941 and have never been found."},"inBooks":{"ar":"فتح «جوياما» الصناديق فجُنّ ذعرًا وأغمد سيفًا في بطنه، والسؤال لرفعت: ماذا رأى؟","en":"Goyama opened the crates, went mad with terror and drove a sword into his belly; the question for Refaat: what did he see?"},"source":"https://en.wikipedia.org/wiki/Peking_Man"},{"id":"side-of-the-stars","name":{"ar":"جانب النجوم","en":"The Side of the Stars"},"kind":"other","issues":["mwt-35","mwt-46","mwt-50"],"lore":{"ar":"يقول أحمد خالد توفيق إنه أسطورة رومانية: المكان الذي تسكنه كل المسوخ، وله ثغرات تعبر منها إلى عالمنا.","en":"Ahmed Khaled Tawfik says it is a Romanian legend: the place where all monsters live, with gaps through which they cross into our world."},"inBooks":{"ar":"يُخدع رفعت إلى جانب النجوم ليحضر محكمة سادته الذين يطالبون الخطاة برواية آثامهم، فيطلق لوسيفر سراحه.","en":"Refaat is tricked onto the Side of the Stars to attend its masters' court, where sinners must tell their sins, and Lucifer sets him free."},"source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"id":"number-13","name":{"ar":"الرقم 13","en":"The number 13"},"kind":"other","issues":["mwt-51"],"lore":{"ar":"التشاؤم من الرقم 13 (التريسكايديكافوبيا) منتشر في الغرب، حتى إن مبانيَ كثيرة بلا طابق ثالث عشر.","en":"Fear of the number 13 (triskaidekaphobia) is widespread in the West; many buildings skip a 13th floor."},"inBooks":{"ar":"رقم مشئوم وحوادث غامضة وشخص غريب الأطوار يعشق الرقم 13 والقطط السوداء، ومعه طبيب أمراض دم حائر.","en":"An ill-omened number, mysterious deaths and an eccentric who loves the number 13 and black cats, plus a puzzled haematologist."},"source":"https://en.wikipedia.org/wiki/13_(number)"},{"id":"nostradamus","name":{"ar":"نبوءة العرّاف","en":"The seer's prophecy"},"kind":"other","issues":["mwt-54"],"lore":{"ar":"تنبأ نوستراداموس، كما يُقال، بموت الملك هنري الثاني في مبارزة: «الأسد الصغير سيهزم الأسد الكبير» وتُفقأ عينه في قفص ذهبي.","en":"Nostradamus is said to have foretold Henry II's death in a joust: \"the young lion will overcome the old\", his eye pierced in a golden cage."},"inBooks":{"ar":"عرّاف يتلو أمام الملكة هذه النبوءة نفسها في البلاط: الأسد الصغير يهزم الأسد الكبير في مبارزة فردية ويموت ميتة شنيعة.","en":"A seer recites this very prophecy to the queen at court: the young lion beats the old in single combat, who dies a horrible death."},"source":"https://en.wikipedia.org/wiki/Nostradamus"},{"id":"beelzebub","name":{"ar":"ملك الذباب","en":"The Lord of the Flies"},"kind":"demon","issues":["mwt-56"],"lore":{"ar":"بعل زبوب، «سيد الذباب»، إله فلسطيني قديم صار في التراث المسيحي اسمًا لأحد أمراء الشياطين.","en":"Beelzebub, \"lord of the flies\", an ancient Philistine god who became one of the princes of demons in Christian tradition."},"inBooks":{"ar":"جسد مغطى بأسراب الذباب، وجون موهون الذي يصير «ري دي موسكاس»؛ ويهرب رفعت إلى المكسيك من لعنته.","en":"A body hidden under swarms of flies, and John Mohun, who becomes \"Rey de Moscas\"; Refaat flees to Mexico to escape his curse."},"source":"https://en.wikipedia.org/wiki/Beelzebub"},{"id":"witch","name":{"ar":"الساحرة","en":"The witch"},"kind":"folk","issues":["mwt-37","mwt-57","mwt-59"],"lore":{"ar":"الساحرة في الفولكلور الأوروبي امرأة تمارس السحر الأسود وتعقد اجتماعات سرية ليلًا، وقد أُحرقت آلاف النساء بهذه التهمة.","en":"In European folklore the witch practises black magic and gathers in secret at night; thousands of women were burned on the charge."},"inBooks":{"ar":"ساحرة في مقبرة ومعها ماجي، ثم الساحرة رونيل السوداء التي تحتل جسد الطفلة إليانور وتتزوج رفعت بوصفة حب.","en":"A witch in a graveyard with Maggie, then the witch Black Ronel, who takes over the girl Eleanor's body and marries Refaat with a love potion."},"source":"https://en.wikipedia.org/wiki/Witchcraft"},{"id":"pandora","name":{"ar":"صندوق باندورا","en":"Pandora's box"},"kind":"myth","issues":["mwt-62"],"lore":{"ar":"في الأساطير الإغريقية فتحت باندورا الجرة التي أعطاها لها زيوس فانطلقت منها شرور العالم ولم يبقَ فيها إلا الأمل.","en":"In Greek myth Pandora opened the jar Zeus gave her and let out the world's evils, leaving only hope inside."},"inBooks":{"ar":"يرسل لوسيفر الصندوق إلى رفعت على سبيل التسلية، فيهز انفجار بلدة كاملة، ويُتهم القمر المكتمل بالعنف الجنوني الذي أصابها.","en":"Lucifer sends Refaat the box for fun, and an explosion rocks a whole town, with the full moon blamed for its mad violence."},"source":"https://en.wikipedia.org/wiki/Pandora's_box"},{"id":"telekinesis","name":{"ar":"التحريك عن بعد","en":"Telekinesis"},"kind":"other","issues":["mwt-63","mwt-64"],"lore":{"ar":"قدرة مزعومة على تحريك الأشياء بالعقل دون لمسها، لم تثبتها أي تجربة علمية.","en":"A claimed power to move objects with the mind alone, never demonstrated in any scientific test."},"inBooks":{"ar":"رفعت يعرف أصحاب هذه الموهبة، ويرى أن الحقيقيين منهم يخفونها ليندمجوا بين الناس.","en":"Refaat knows people with the gift and believes the real ones hide it to blend in among others."},"source":"https://en.wikipedia.org/wiki/Psychokinesis"},{"id":"shadows","name":{"ar":"قوم الظلال","en":"The shadow people"},"kind":"other","issues":["mwt-71"],"lore":{"ar":"يرى الناس في التراث وفي حكايات الخوارق أشباحًا على هيئة ظلال، ومن لا ظل له في الأساطير مسخ أو ميت.","en":"Folklore and paranormal tales speak of shadow-shaped figures, and in legend whoever casts no shadow is a monster or the dead."},"inBooks":{"ar":"موعظة بسيطة: لا تثق بمن لا ظل له، والأسوأ منه من يتصرف ظله وحده.","en":"A simple moral: never trust anyone without a shadow, and fear even more the one whose shadow acts on its own."},"source":"https://en.wikipedia.org/wiki/Shadow_person"},{"id":"totem","name":{"ar":"الطوطم","en":"The totem"},"kind":"other","issues":["mwt-72"],"lore":{"ar":"الطوطم كائن أو رمز تتخذه قبيلة جدًا روحيًا لها، وأشهره أعمدة الطواطم المنحوتة عند سكان شمال غرب أمريكا الأصليين.","en":"A totem is a being or emblem a clan takes as its spirit ancestor, best known from the carved totem poles of the Pacific Northwest peoples."},"inBooks":{"ar":"شيء يتحرك في المتحف بعد حلول الظلام، ينتزع الأطراف ولا تسجله الكاميرات، فيستنجدون برفعت.","en":"Something moves in the museum after dark, tearing off limbs and invisible to cameras, so they turn to Refaat."},"source":"https://en.wikipedia.org/wiki/Totem"},{"id":"lucifer","name":{"ar":"لوسيفر، حامل الضياء","en":"Lucifer, the Light-Bearer"},"kind":"demon","issues":["mwt-20","mwt-34","mwt-50","mwt-62","mwt-78","mwt-79"],"lore":{"ar":"لوسيفر بالاتينية «حامل الضياء»، اسم كوكب الصبح، صار في التراث المسيحي اسمًا للشيطان قبل سقوطه.","en":"Lucifer, Latin for \"light-bearer\", the name of the morning star, became in Christian tradition a name of Satan before his fall."},"inBooks":{"ar":"د. فرانتز لوسيفر، قارئ التاروت الذي يراه رفعت تجسيدًا للشيطان، يطارده من نيويورك 1968 حتى «حامل الضياء».","en":"Dr. Franz Lucifer, the tarot reader Refaat takes for the devil incarnate, haunts him from New York in 1968 to \"The Light-Bearer\"."},"source":"https://en.wikipedia.org/wiki/Lucifer"},{"id":"tarot","name":{"ar":"أوراق التاروت","en":"Tarot cards"},"kind":"other","issues":["mwt-20"],"lore":{"ar":"أوراق لعب ظهرت في إيطاليا في القرن الخامس عشر، ثم صارت منذ القرن الثامن عشر أداة لقراءة الطالع.","en":"Playing cards from 15th-century Italy that became a fortune-telling tool from the 18th century on."},"inBooks":{"ar":"لوسيفر يقرأ الأوراق لعدد من الغرباء فيزرع في أذهانهم نهايات شنيعة تتحقق.","en":"Lucifer reads the cards for a group of strangers and plants horrible fates in their minds that then come true."},"source":"https://en.wikipedia.org/wiki/Tarot"},{"id":"crowley","name":{"ar":"أليستر كراولي","en":"Aleister Crowley"},"kind":"other","issues":["mwt-78","mwt-79"],"lore":{"ar":"ساحر وكاتب بريطاني (1875–1947) أسس مذهب «ثيليما»، ولقبته الصحافة «أشر رجل في العالم» وسمى نفسه «الوحش 666».","en":"A British occultist and writer (1875–1947) who founded Thelema; the press called him \"the wickedest man in the world\" and he called himself \"the Beast 666\"."},"inBooks":{"ar":"يجلس رفعت مع كراولي الميت منذ سبعين عامًا يتحدثان عن لوسيفر، وتُعيد محاولات كولبي الحمقاء إحياءه.","en":"Refaat sits down with Crowley, dead some seventy years, to talk about Lucifer, after Colby's foolish attempts bring him back."},"source":"https://en.wikipedia.org/wiki/Aleister_Crowley"},{"id":"book-of-thoth","name":{"ar":"كتاب تحوت","en":"The Book of Thoth"},"kind":"myth","issues":["mwt-78","mwt-79"],"lore":{"ar":"في حكايات مصر القديمة كتاب سحري كتبه الإله تحوت بيده، ويمنح قارئه فهم لغة الحيوان وسر الآلهة، كما في قصة ستني خعمواس.","en":"In ancient Egyptian tales a magic book written by the god Thoth himself, granting its reader the speech of animals and the gods' secrets, as in the story of Setne Khamwas."},"inBooks":{"ar":"يفتش لوسيفر في ذكريات أجداد رفعت داخل عقله عن الكتاب الذي خبأه جده الأكبر الحكيم سمعان.","en":"Lucifer searches the memories of Refaat's ancestors inside his mind for the book his forefather, the sage Simeon, hid."},"source":"https://en.wikipedia.org/wiki/Book_of_Thoth"},{"id":"necronomicon","name":{"ar":"كتاب العزيف","en":"Al Azif (the Necronomicon)"},"kind":"other","issues":[],"lore":{"ar":"كتاب سحري مختلق في قصص لافكرافت، نسبه إلى «العربي المجنون» عبد الله الحظرد، واسمه العربي «العزيف».","en":"A fictional grimoire in H. P. Lovecraft's stories, credited to \"the mad Arab\" Abdul Alhazred; its Arabic title is \"Al Azif\"."},"inBooks":{"ar":"تطارد الشياطين رفعت بسبب ما يعرفه عن كتاب العزيف، فيحتاج إلى سام كولبي ليخلّصه منها.","en":"Demons hunt Refaat because of what he knows of the book Al Azif, and he needs Sam Colby to rid him of them."},"source":"https://en.wikipedia.org/wiki/Necronomicon"},{"id":"atlantis","name":{"ar":"أطلنطس","en":"Atlantis"},"kind":"myth","issues":["mwt-80"],"lore":{"ar":"جزيرة ذكرها أفلاطون في محاورتي «طيماوس» و«كريتياس»، قال إنها غرقت في البحر في يوم وليلة.","en":"An island described by Plato in the Timaeus and Critias, which he said sank into the sea in a single day and night."},"inBooks":{"ar":"من الأسئلة المعلقة التي يجيب عنها العدد الأخير: «هل هناك أطلنطس حقًّا؟»","en":"One of the open questions the final issue sets out to answer: \"Is there really an Atlantis?\""},"source":"https://en.wikipedia.org/wiki/Atlantis"},{"id":"borley-rectory","name":{"ar":"بيت بورلي","en":"Borley Rectory"},"kind":"other","issues":["mwt-80"],"lore":{"ar":"بيت قسيس في إسكس بإنجلترا لُقب «أكثر بيوت إنجلترا المسكونة»، واحترق عام 1939.","en":"A rectory in Essex, England, dubbed \"the most haunted house in England\", which burned down in 1939."},"inBooks":{"ar":"«أين بيت بورلي؟» سؤال من أسئلة السلسلة التي حان وقت الإجابة عنها في «أسطورة الأساطير».","en":"\"Where is Borley Rectory?\" is one of the series' questions that \"The Legend of Legends\" finally answers."},"source":"https://en.wikipedia.org/wiki/Borley_Rectory"},{"id":"haunted-house","name":{"ar":"البيت المسكون","en":"The haunted house"},"kind":"other","issues":["mwt-12","mwt-47","mwt-67"],"lore":{"ar":"بيت يُعتقد أن أرواحًا أو قوى خفية تسكنه، من أقدم ثيمات حكايات الأشباح منذ رسائل بليني الأصغر.","en":"A house believed to be inhabited by spirits or unseen forces, one of the oldest ghost-story themes, going back to Pliny the Younger."},"inBooks":{"ar":"بيت في المنصورة صنع لرفعت وأبناء خاله صديقة وهمية اسمها شيراز، وعاد يطاردهم بعد عقود حتى أحرقوه.","en":"A house in Mansoura conjured an imaginary playmate, Shiraz, for Refaat and his cousins, and came after them decades later until they burned it."},"source":"https://en.wikipedia.org/wiki/Haunted_house"},{"id":"ghost","name":{"ar":"الشبح","en":"The ghost"},"kind":"undead","issues":["mwt-10","mwt-60"],"lore":{"ar":"روح الميت حين تظهر للأحياء، وتؤمن بها ثقافات كثيرة منذ القدم.","en":"The spirit of a dead person appearing to the living, believed in by many cultures since antiquity."},"inBooks":{"ar":"شبح شاكر بك يحضر حلقة الرعب الأولى في صورة أحد الحاضرين، وشبح مازن أبو سيف يحكي لرفعت حكايات «المتحف الأسود».","en":"The ghost of Shaker Bey attends the first Horror Circle disguised as a guest, and the ghost of Mazen Abu Seif tells Refaat the tales of \"The Black Museum\"."},"source":"https://en.wikipedia.org/wiki/Ghost"}];
window.AKT.glossary = [{"phrase":"حتى تحترق النجوم","en":"Until the stars burn out","who":"refaat","meaning":{"ar":"جواب رفعت حين تسأله ماجي «للأبد؟»، وصار عهد الحب الأشهر في السلسلة. تتكرر في «وحش البحيرة» و«أسطورتها» حتى المشهد الأخير في «أسطورة الأساطير»، ويستعيرها القراء لكل وفاء طويل.","en":"Refaat's answer when Maggie asks «Forever?». It became the series' best-known vow of love, returning in Lake Monster, Ostoret-ha and the last scene of The Legend of Legends, and readers borrow it for any lasting loyalty."},"where":"mwt-3","source":"https://www.abjjad.com/quote/788983447552"},{"phrase":"«للأبد؟» — «ماذا؟»","en":"«Forever?» — «What?»","who":"other","meaning":{"ar":"الحوار القصير بين ماجي ورفعت الذي يسبق دائمًا عبارة «حتى تحترق النجوم»، وتعود ماجي لتهمس به في أذنه وهو يحتضر في العدد الأخير.","en":"The short exchange between Maggie and Refaat that always comes before «until the stars burn out». Maggie whispers it again in his ear as he dies in the final issue."},"where":"mwt-80","source":"https://www.goodreads.com/quotes/1341255"},{"phrase":"أصلع الرأس.. نحيل كالبعوضة.. تحش صدره أبخرة التبغ","en":"Bald-headed, thin as a mosquito, his chest stuffed with tobacco fumes","who":"refaat","meaning":{"ar":"صورة رفعت الساخرة لنفسه: عجوز أصلع نحيل مدخن مريض بالقلب، وهو مع ذلك يحب. السخرية من جسده من أثبت ملامح شخصيته.","en":"Refaat's mocking self-portrait: a bald, skinny, chain-smoking old man with a bad heart, who is in love all the same. Making fun of his own body is one of his most constant traits."},"where":"mwt-12","source":"https://www.abjjad.com/quote/446103620"},{"phrase":"إنني أبدو رائعًا حينما تلتمع صلعتي في ضوء الشمس","en":"I look wonderful when my bald head gleams in the sunlight","who":"refaat","meaning":{"ar":"غرور رفعت الساخر المقلوب: يتباهى بالعيب نفسه الذي يسخر منه طوال الوقت.","en":"Refaat's mock vanity: he shows off the very flaw he jokes about all the time."},"where":"specials-4","source":"https://www.abjjad.com/quote/788889370814"},{"phrase":"دورة مياه الشهيد (رفعت إسماعيل)!","en":"The Martyr Refaat Ismail Restroom!","who":"refaat","meaning":{"ar":"يتخيل رفعت، في العدد الأول، كيف ستخلّد كلية الطب ذكراه إن مات في مغامرته: بإطلاق اسمه على دورة المياه. من أوائل نكاته عن نفسه وأشهرها.","en":"In the very first issue Refaat imagines how the medical school would honour him if he died on his adventure: by naming its restroom after him. One of his earliest and best-known jokes at his own expense."},"where":"mwt-1","source":"https://www.abjjad.com/quote/788983283716"},{"phrase":"كح كح!.. اللعنة!","en":"Cough, cough! Damn it!","who":"refaat","meaning":{"ar":"سعال المدخن العجوز مكتوبًا على الورق، يقطع كلام رفعت ويتبعه سبابه المتذمر. رفعت والسعال والسجائر لا يفترقون في السلسلة.","en":"The old smoker's cough written out on the page, interrupting Refaat's speech and followed by his grumbling curse. Refaat, coughing and cigarettes go together throughout the series."},"where":"mwt-5","source":"https://www.abjjad.com/quote/788987379731"},{"phrase":"يا للهول!","en":"Oh, the horror!","who":"refaat","meaning":{"ar":"تعجب رفعت المسرحي القديم، يطلقه حين يدرك فداحة موقفه ثم ينتقل إلى الشكوى من وحدته.","en":"Refaat's old-fashioned, theatrical exclamation, used when he realises how bad his situation is, before he goes on to lament his loneliness."},"where":"mwt-21","source":"https://www.abjjad.com/quote/454230068"},{"phrase":"إرادة النكد","en":"The will to misery","who":"refaat","meaning":{"ar":"صياغة ساخرة على وزن «إرادة الحياة» و«إرادة القوة»: قوة غامضة تفسد كل علاقة سعيدة دون سبب، ويضعها الراوي مع «إرادة الفشل» و«إرادة الموت».","en":"A mocking coinage modelled on «the will to live» and «the will to power»: a mysterious force that ruins every happy relationship for no reason, which the narrator lists alongside «the will to fail» and «the will to die»."},"where":"mwt-29","source":"https://www.goodreads.com/quotes/9090219"},{"phrase":"تعلمت ألا أندهش لشيء، وتعلمت أننا جميعًا حفنة من الأوغاد","en":"I have learned to be surprised by nothing, and that we are all a bunch of scoundrels","who":"refaat","meaning":{"ar":"خلاصة رفعت المتشائمة عن الطبيعة البشرية، وتكملتها أنه لا ينقذنا من العذاب سوى رحمة الله. يكثر القراء من نسبتها إليه.","en":"Refaat's pessimistic verdict on human nature; it ends by saying only God's mercy can save us from damnation. Readers quote it under his name more than almost any other line."},"where":"mwt-39","source":"https://www.abjjad.com/quote/788990394368"},{"phrase":"تكنيك النعامة الشهير: ما لا نراه نحن هو على الأرجح غير موجود","en":"The famous ostrich technique: what we can't see probably doesn't exist","who":"refaat","meaning":{"ar":"طريقة رفعت الساخرة في التعامل مع الخطر الخارق: أن يتجاهله كأن الإنكار يلغيه، وهي سخرية من عناده المتشكك نفسه.","en":"Refaat's tongue-in-cheek way of handling supernatural danger: ignore it, as if denial could make it vanish. It also pokes fun at his own sceptical stubbornness."},"where":"mwt-51","source":"https://www.goodreads.com/quotes/375630"},{"phrase":"لست (صانع أساطير) بل (هادم أساطير)","en":"I am not a maker of legends but a breaker of legends","who":"refaat","meaning":{"ar":"تعريف رفعت لدوره: الطبيب العقلاني الذي يحاول تفسير الأسطورة وتفنيدها، مع أن كل عدد يحمل اسم «أسطورة».","en":"Refaat's definition of his role: the rational doctor who tries to explain and debunk the legend, even though every issue is titled «The Legend of…»."},"where":"mwt-7","source":"https://www.abjjad.com/quote/788916143085"},{"phrase":"معظم الأشياء اللذيذة حرام دينيًّا أو ممنوعة قانونًا أو تسبب السمنة أو ترفع الضغط","en":"Most delicious things are religiously forbidden, illegal, fattening or bad for your blood pressure","who":"refaat","meaning":{"ar":"حكمة رفعت الساخرة عن متع الحياة، من أكثر سطوره تداولًا خارج السلسلة.","en":"Refaat's wry rule about life's pleasures, one of his lines most often shared outside the series."},"where":"mwt-78","source":"https://www.abjjad.com/quote/447938591"},{"phrase":"رباعية اللون الأسود: الشاي، القهوة، الكولا، الدخان","en":"The black quartet: tea, coffee, cola, tobacco","who":"refaat","meaning":{"ar":"تسمية طبيب القلب لما يحبه مرضى الشرايين ويقودهم إلى القبر، وهي قائمة عادات رفعت نفسه.","en":"A cardiologist's name for the four things heart patients love and that lead them to the grave, which is also a list of Refaat's own habits."},"where":"mwt-32","source":"https://www.abjjad.com/quote/455114760"},{"phrase":"لا تقلقي على (رفعت).. إن حياته كلها كارثة طويلة لا تنتهي","en":"Don't worry about Refaat: his whole life is one long, endless disaster","who":"other","meaning":{"ar":"وصف أصدقاء رفعت لحظه السيئ المزمن، وهو أساس السلسلة: الكوارث تجد رفعت أينما ذهب.","en":"How Refaat's friends sum up his chronic bad luck, which is the premise of the series: disaster finds Refaat wherever he goes."},"where":"mwt-46","source":"https://www.abjjad.com/quote/788941537283"},{"phrase":"هذا عالم ما وراء الطبيعة يا صاحبي وليس فاتورة البقال","en":"This is the world beyond nature, my friend, not the grocer's bill","who":"refaat","meaning":{"ar":"رد رفعت حين يطالبه أحد بإجابات قاطعة: في عالم المجهول لا توجد حسابات دقيقة، وسنموت دون أن نعرف.","en":"Refaat's reply when someone demands clear-cut answers: the unknown can't be added up neatly, and we will die without knowing."},"where":"mwt-70","source":"https://www.goodreads.com/quotes/8070635"},{"phrase":"لا يوجد كلب ذكر إلا واسمه (روي)، ولا توجد كلبة إلا واسمها (توسكا)","en":"Every male dog is called Roy, and every female dog is called Toska","who":"refaat","meaning":{"ar":"ملاحظة رفعت الساخرة عن أسماء الكلاب المتكررة في الأفلام والحياة المصرية، ويختمها بقوله «هذا هو القانون».","en":"Refaat's joke about the dog names that turn up again and again in films and in Egyptian life, ending with «that is the law»."},"where":"mwt-70","source":"https://www.abjjad.com/quote/472252478"},{"phrase":"أنا أحب الأوغاد المنطقيين","en":"I like logical scoundrels","who":"refaat","meaning":{"ar":"إعجاب رفعت المعكوس بالخصم الذي يتكلم كلامًا سليمًا منطقيًّا، لأن العقل عنده يعلو على الطيبة.","en":"Refaat's backhanded admiration for an opponent who talks sound logic, since he values reason above niceness."},"where":"mwt-44","source":"https://www.abjjad.com/quote/483492267"},{"phrase":"إنني لشديد الحماس.. لكني لا أعرف كيف أظهر حماسي","en":"I am very enthusiastic, I just don't know how to show it","who":"refaat","meaning":{"ar":"يقولها رفعت «في ملل» حين يُسأل عن رأيه، وهي من أصدق صور بروده الساخر وضجره الدائم.","en":"Refaat says it «in boredom» when asked for his opinion. It is one of the clearest pictures of his deadpan coolness and constant boredom."},"where":"mwt-30","source":"https://www.abjjad.com/quote/788948189301"},{"phrase":"المرأة هي المرأة","en":"A woman is a woman","who":"refaat","meaning":{"ar":"حكم رفعت المتكرر حين يرى امرأة تتصرف كما يتوقع، ومنه: «يسحرها الإطراء حتى ولو كانت عجوزًا شمطاء.. وساحرة فودو». تعود الصيغة في «فانتازيا» أيضًا.","en":"Refaat's recurring verdict when a woman behaves as he expects, as in «flattery charms her even if she is a haggard old crone… and a voodoo witch». The formula returns in Fantasia too."},"where":"mwt-5","source":"https://www.abjjad.com/quote/788989018129"},{"phrase":"أنا يا رفاق أخشى الموت كثيرًا","en":"Me, friends? I am very afraid of death","who":"refaat","meaning":{"ar":"«يا رفاق» هو نداء رفعت لقرائه وهو يحكي لهم مذكراته. هنا يعترف بخوفه بدل ادعاء البطولة، فمن لا يخشى الموت عنده «أحمق أو واهن الإيمان».","en":"«Friends» is how Refaat addresses his readers as he tells them his memoirs. Here he admits his fear instead of playing the hero: to him, anyone unafraid of death is «a fool or weak in faith»."},"where":"mwt-21","source":"https://www.goodreads.com/quotes/692959"},{"phrase":"إنني -كعهدي- ذلك الذئب الوحيد الذي لا يملك أصدقاء","en":"As ever, I am that lone wolf with no friends","who":"refaat","meaning":{"ar":"صورة رفعت عن نفسه: أعزب منطوٍ يعيش وحيدًا، وهي وحدة يشكو منها ويتباهى بها في آن.","en":"Refaat's image of himself as an introverted bachelor living alone, a solitude he both complains about and is proud of."},"where":"mwt-4","source":"https://www.goodreads.com/quotes/9359301"},{"phrase":"(فانتازيا) حيث كل شيء ممكن.. وكل حلم متاح","en":"Fantasia, where everything is possible and every dream is within reach","who":"abeer","meaning":{"ar":"تعريف عالم فانتازيا في العدد الأول، ومعه «أرض الأحلام التي لا تنتهي» و«جنة عاشقي الخيال». صارت شعار السلسلة.","en":"How the first issue defines the world of Fantasia, alongside «the land of endless dreams» and «the paradise of those who love imagination». It became the series' motto."},"where":"fantasia-1","source":"https://www.abjjad.com/quote/788990492714"},{"phrase":"حيث القواعد الوحيدة للعبة هي: لا قواعد","en":"Where the only rule of the game is: no rules","who":"abeer","meaning":{"ar":"وصف آخر لفانتازيا، وتكملته: «وحيث الحدود الوحيدة لرقعة الخيال هي: لا حدود».","en":"Another description of Fantasia, which goes on: «and where the only limit to imagination's board is: no limits»."},"where":"fantasia-59","source":"https://www.abjjad.com/quote/788914602102"},{"phrase":"لم تكن (عبير) جميلة ولا مثقفة ولا قوية.. لكنها تملك القدرة على الحلم","en":"Abeer was neither beautiful, nor cultured, nor strong, but she could dream","who":"abeer","meaning":{"ar":"تقديم البطلة في العدد الأول: فتاة عادية تمامًا، ميزتها الوحيدة خيالها، ولهذا «غدا الكون كله طوعًا لها».","en":"How the first issue introduces its heroine: a perfectly ordinary girl whose only gift is her imagination, which is why «the whole universe became hers to command»."},"where":"fantasia-1","source":"https://www.abjjad.com/quote/472907783"},{"phrase":"(عبير) ملكة جمال الأرواح","en":"Abeer, Miss Beautiful Soul","who":"abeer","meaning":{"ar":"لقب يمنحه الراوي لعبير: ليست ملكة جمال لكنها جميلة الروح، «إذا وجد لقب كهذا يومًا ما».","en":"A title the narrator gives Abeer: no beauty queen, but beautiful in spirit, «if such a title ever existed»."},"where":"fantasia-1","source":"https://www.abjjad.com/quote/788990492712"},{"phrase":"هي تقرأ كي تستمتع، ولا تقرأ كي تؤدي واجبًا وطنيًّا","en":"She reads for pleasure, not to do her patriotic duty","who":"abeer","meaning":{"ar":"دفاع عن قراءة عبير للروايات بدل الكتب «الجادة»، وهي فكرة المؤلف نفسه عن القراءة للمتعة.","en":"A defence of Abeer reading novels instead of «serious» books, and the author's own view of reading for pleasure."},"where":"fantasia-1","source":"https://www.abjjad.com/quote/468221971"},{"phrase":"ثمة أبطال يمتازون بأنهم لا يمتازون بشيء!","en":"Some heroes stand out by not standing out at all!","who":"abeer","meaning":{"ar":"تلخيص لفلسفة «فانتازيا» ورفعت وعلاء معًا: أبطال عاديون بلا قوى خارقة.","en":"A summary of the philosophy behind Fantasia, and Refaat and Alaa too: ordinary heroes with no superpowers."},"where":"fantasia-36","source":"https://www.abjjad.com/quote/84672517"},{"phrase":"قدر هائل من الرومانسية لم يستعمل قط حتى صدئ","en":"A huge store of romance, never used until it rusted","who":"abeer","meaning":{"ar":"صورة متكررة في فانتازيا عن عاطفة مكبوتة لم تجد من يستحقها. تعود في «الملل بعينه» عن عبير: «حتى صارت كسيف صدئ».","en":"A recurring image in Fantasia of pent-up feeling that never found a worthy object. It returns in Boredom Itself about Abeer: «until it was like a rusted sword»."},"where":"fantasia-36","source":"https://www.abjjad.com/quote/483688911"},{"phrase":"الكوكلة والكنتكة والمكدلة","en":"Coca-colafication, Kentuckification and McDonaldization","who":"akt","meaning":{"ar":"ألفاظ نحتها على أوزان عربية من كوكاكولا وكنتاكي وماكدونالدز، ليسخر من غزو نمط الحياة الأمريكي لكل شيء.","en":"Words he coined on Arabic verb patterns from Coca-Cola, KFC and McDonald's to mock the American way of life invading everything."},"where":"fantasia-17","source":"https://www.abjjad.com/quote/789003239593"},{"phrase":"جعلوه فانجعل","en":"They made him, so he was made","who":"akt","meaning":{"ar":"تعبير ساخر يصف الشخص السلبي الذي يُشكَّل كما يريد غيره ولا يقاوم. يستعمله في السلاسل الثلاث، فهو «أسلوب (جعلوه فانجعل) الشهير» في «سافاري»، ويرد في «ما وراء الطبيعة» و«فانتازيا».","en":"A sarcastic phrase for a passive person who lets others shape him without resisting. He uses it in all three series: «the famous they-made-him-so-he-was-made style» in Safari, and again in Ma Wara' al-Tabi'a and Fantasia."},"where":"safari-10","source":"https://www.abjjad.com/quote/453148724"},{"phrase":"طبيب مصري شاب يجاهد كي يبقى حيًّا ويبقى طبيبًا","en":"A young Egyptian doctor struggling to stay alive and stay a doctor","who":"alaa","meaning":{"ar":"تعريف علاء عبد العظيم لنفسه «كما يقول الغلاف» في العدد الأول، ويعود إليه لاحقًا: «من العسير أن تجمع بين شيئين: أن تظل حيًّا وتظل طبيبًا».","en":"Alaa Abdel Azim's description of himself in the first issue, «as the cover says». He comes back to it later: «it is hard to do two things at once: stay alive and stay a doctor»."},"where":"safari-1","source":"https://www.abjjad.com/quote/445808674"},{"phrase":"لن أكون الحمار الأخير في هذا العالم","en":"I won't be the last donkey in this world","who":"alaa","meaning":{"ar":"عزاء علاء الساخر عن اندفاعه المتهور: «أتكلم وأفعل ثم أفكر»، وليس هو أول أحمق ولا آخرهم.","en":"Alaa's wry comfort about his rashness («I speak and act, then think»): he is neither the first fool nor the last."},"where":"safari-30","source":"https://www.abjjad.com/quote/446922810"},{"phrase":"الهاتف الجوال لا يعمل أبدًا عندما تحتاج له","en":"The mobile phone never works when you need it","who":"alaa","meaning":{"ar":"«قاعدة لا تخيب» يكررها علاء بصيغ مختلفة، فهي في «إنهم يكذبون»: «متى أردت المحمول جدًّا فهو قطعة من البلاستيك بلا نفع».","en":"An «infallible rule» Alaa repeats in different words. In They Are Lying it reads: «whenever you really need the mobile, it's a useless lump of plastic»."},"where":"safari-49","source":"https://www.abjjad.com/quote/788932788226"},{"phrase":"هوايتي لاجتذاب المتاعب","en":"My hobby of attracting trouble","who":"alaa","meaning":{"ar":"اعتراف علاء بأن المشاكل تلاحقه كما تلاحق رفعت، فالأيام ستكون سارة «ما لم تلاحقني» هذه الهواية.","en":"Alaa admits that trouble follows him as it follows Refaat: the days ahead will be pleasant «unless my hobby of attracting trouble catches up with me»."},"where":"safari-42","source":"https://www.abjjad.com/quote/789000323072"},{"phrase":"صوت الحوافر يجعلك تفكر في الخيول لا الحمير الوحشية","en":"Hoofbeats should make you think of horses, not zebras","who":"alaa","meaning":{"ar":"«القاعدة الطبية الأولى» في «سافاري»: ابدأ بالتشخيص الشائع قبل النادر. هي حكمة معروفة في تعليم الطب، ينقلها إلى أدغال أفريقيا.","en":"«The first medical rule» in Safari: think of the common diagnosis before the rare one. It is a well-known maxim of medical teaching, carried into the African bush."},"where":"safari-20","source":"https://www.abjjad.com/quote/446595166"},{"phrase":"إن من لا يحب (برنادت) لم يولد بعد","en":"Whoever doesn't love Bernadette hasn't been born yet","who":"alaa","meaning":{"ar":"حب علاء لبرنادت، زميلته الفرنسية في «سافاري» وحب حياته، التي «تذكرني بميكي ماوس أو شارلي شابلن»: شيء عالمي يحبه الجميع.","en":"Alaa's love for Bernadette, his French colleague at Safari and the love of his life, who «reminds me of Mickey Mouse or Charlie Chaplin»: something universal that everyone loves."},"where":"safari-26","source":"https://www.abjjad.com/quote/448593932"},{"phrase":"كتكوت سقط في إناء شربة.. هذا هو أنا","en":"A chick fallen into a pot of soup: that's me","who":"alaa","meaning":{"ar":"تشبيه علاء الساخر لنفسه وهو غارق في ورطة أكبر منه بلا حول ولا قوة.","en":"Alaa's mocking picture of himself, helplessly stuck in a mess too big for him."},"where":"safari-14","source":"https://www.abjjad.com/quote/446365700"},{"phrase":"جعل الشباب يقرأون","en":"He made the young read","who":"akt","meaning":{"ar":"العبارة التي تمنى أن تُكتب على قبره، ردًّا على أمنية ر. ل. شتاين «جعل الأطفال يقرأون». صارت أشهر ما يقال عنه بعد رحيله.","en":"The line he wished to have on his grave, answering R. L. Stine's wish «he made children read». After his death it became the thing most often said about him."},"where":null,"source":"https://www.goodreads.com/quotes/198255"},{"phrase":"العرّاب","en":"The Godfather","who":"other","meaning":{"ar":"اللقب الذي أطلقه قراؤه عليه، لأنه رعى أجيالًا من القراء والكتّاب الشباب الذين دخلوا الأدب من باب سلاسله.","en":"The nickname his readers gave him, because he fostered generations of young readers and writers who came to literature through his series."},"where":null,"source":"https://www.egypttelegraph.com/63739"},{"phrase":"عزاؤك الوحيد إذا مت بعد الخامسة والأربعين هو أنك لم تمت شابًا","en":"If you die after forty-five, your only consolation is that you didn't die young","who":"akt","meaning":{"ar":"«قول قديم ساخر» يستشهد به في «قهوة باليورانيوم» وهو يتأمل موعدًا توقعه لموته.","en":"An «old sarcastic saying» he cites in Coffee with Uranium while reflecting on a date he once predicted for his own death."},"where":"qahwa","source":"https://www.egypttelegraph.com/63739"},{"phrase":"عندما تغير الطابور فإن الطابور الذي تركته سوف يتحرك أسرع","en":"When you switch queues, the one you left will move faster","who":"akt","meaning":{"ar":"«قانون الطابور»، من سلسلة قوانين على طريقة «مورفي» جمعها في «زغازيغ» عن نحس الحياة اليومية.","en":"«The law of the queue», one of a set of Murphy-style laws about everyday bad luck in Zaghazigh."},"where":"zaghazigh","source":"https://www.goodreads.com/quotes/520579"},{"phrase":"تصوف الروشنة","en":"Trendy Sufism","who":"akt","meaning":{"ar":"تسميته الساخرة لموضة «التصوف السطحي الصناعي» بين الشباب بعد رواية «قواعد العشق الأربعون». و«الروشنة» من مفرداته الأثيرة في السخرية من موضات الشباب.","en":"His mocking name for the fad of «shallow, manufactured Sufism» among young people after the novel The Forty Rules of Love. «Rawshana» (being trendy) is one of his favourite words for mocking youth fads."},"where":"laghz","source":"https://www.goodreads.com/quotes/9448002"}];
window.AKT.tanta = [{"id":"birth-house-limonos","name":{"ar":"بيت الميلاد فوق مقهى «ليمونوس» – شارع البحر","en":"Birth house above Café Limonos, Shari' al-Bahr"},"kind":"home","lat":null,"lng":null,"text":{"ar":"وُلد في 10 يونيو 1962 في بيت يعلو مقهى «ليمونوس» الشهير في شارع البحر بطنطا، وكان له فيه جار يوناني أحبه وتعلّق به. وكتب لاحقًا أن مقهى ليمنوس ما زال قائمًا في شارع البحر.","en":"He was born on 10 June 1962 in a house above the well-known Café Limonos on Shari' al-Bahr in Tanta, where he had a Greek neighbour he was fond of. He later wrote that Café Limnos still stands on Shari' al-Bahr."},"year":1962,"source":"https://www.dostor.org/5487332"},{"id":"tharwat-street-home","name":{"ar":"بيته في 9 شارع ثروت (عمارة مبروك الجمل) – حي ثانٍ طنطا","en":"His home at 9 Tharwat Street (Mabrouk al-Gamal building), Tanta District 2"},"kind":"home","lat":null,"lng":null,"text":{"ar":"عاش في شارع ثروت المتفرع من شارع حسن رضوان، وهو شارع جانبي غير مرصوف؛ وروى جيرانه، ومنهم صاحب البقالة المقابلة الحاج إبراهيم، أنه كان يتسوّق منهم بتواضع لأكثر من عشر سنوات.","en":"He lived on Tharwat Street, an unpaved side street off Hassan Radwan Street; neighbours, including the grocer opposite, Hajj Ibrahim, recalled him shopping there modestly for over ten years."},"year":null,"source":"https://www.youm7.com/story/2018/4/4/هنا-عاش-العراب-رحلة-البحث-عن-منزل-أحمد-خالد-توفيق/3729868"},{"id":"lived-here-plaque","name":{"ar":"لافتة «عاش هنا» على منزله","en":"The 'Lived Here' plaque on his home"},"kind":"memorial","lat":null,"lng":null,"text":{"ar":"مساء 30 أبريل 2019 ثبّت الجهاز القومي للتنسيق الحضاري لافتة نحاسية بالعربية والإنجليزية على منزله نصها: «عاش هنا الأديب أحمد خالد توفيق، 9 شارع ثروت، حي ثانٍ، محافظة الغربية، طنطا»، بحضور نجله د. محمد.","en":"On the evening of 30 April 2019 the National Organization for Urban Harmony fixed a bilingual brass plaque to his house reading 'The writer Ahmed Khaled Tawfik lived here, 9 Tharwat Street, District 2, Gharbia, Tanta', with his son Dr Mohamed present."},"year":2019,"source":"https://www.shorouknews.com/news/view.aspx?cdate=30042019&id=b9fc790c-b82d-4ee6-bd6d-3d1fa2481ba1"},{"id":"al-islah-primary-school","name":{"ar":"مدرسة الإصلاح الابتدائية","en":"Al-Islah Primary School"},"kind":"school","lat":null,"lng":null,"text":{"ar":"مدرسته الابتدائية، وكانت قصرًا لأحد أمراء الأسرة المالكة تحوّل إلى مدرسة بعد 1952. كتب عنها «ذكريات مدرسة الإصلاح» (التحرير، 2013)، وذكر لوحة بيكار عند مدخلها التي ساعد مدرّس الرسم في لمساتها الأخيرة.","en":"His primary school, a former royal prince's palace turned into a school after 1952. He wrote about it in 'Memories of Al-Islah School' (Al-Tahrir, 2013), recalling the Bikar painting at its entrance that he helped his art teacher finish."},"year":null,"source":"https://aktowfik.blogspot.com/2013/05/blog-post_13.html"},{"id":"said-el-eryan-prep-school","name":{"ar":"مدرسة سعيد العريان الإعدادية","en":"Said El-Eryan Preparatory School"},"kind":"school","lat":null,"lng":null,"text":{"ar":"قضى فيها المرحلة الإعدادية؛ وكانت مدارسه كلها حكومية، ولم يأخذ دروسًا خصوصية في أي مرحلة.","en":"He attended it for his preparatory years; all his schools were state schools, and he took no private tutoring at any stage."},"year":null,"source":"https://www.dostor.org/5487379"},{"id":"coptic-secondary-school","name":{"ar":"مدرسة الأقباط (الثانوية)","en":"Al-Aqbat (Coptic) School – secondary"},"kind":"school","lat":null,"lng":null,"text":{"ar":"درس المرحلة الثانوية في مدرسة الأقباط الحكومية بطنطا قبل التحاقه بكلية الطب.","en":"He did his secondary schooling at the state-run Al-Aqbat (Coptic) School in Tanta before entering medical school."},"year":null,"source":"https://www.dostor.org/5487379"},{"id":"tanta-faculty-of-medicine","name":{"ar":"كلية الطب – جامعة طنطا، قسم طب المناطق الحارة","en":"Faculty of Medicine, Tanta University – Tropical Medicine Department"},"kind":"university","lat":null,"lng":null,"text":{"ar":"تخرّج فيها عام 1985 ونال منها الدكتوراه في طب المناطق الحارة عام 1997، وظل عضوًا بهيئة تدريسها؛ ويذكره موقع الكلية «أستاذًا ورئيسًا لمجلس قسم طب المناطق الحارة والأمراض المعدية».","en":"He graduated there in 1985, took his doctorate in tropical medicine there in 1997 and stayed on its faculty; the faculty's site lists him as professor and head of the council of the Tropical Medicine and Infectious Diseases department."},"year":1985,"source":"https://med.tanta.edu.eg/depart_tropical_fever/council.aspx"},{"id":"tanta-university-hospital","name":{"ar":"مستشفى طنطا الجامعي","en":"Tanta University Hospital"},"kind":"hospital","lat":null,"lng":null,"text":{"ar":"عمل فيه طبيبَ امتياز عام 1986، ومرّ بعنبر الحروق والحوادث، وكتب عن تلك الأيام في مقاله «امرأتان» (اليوم الجديد، 2016).","en":"He worked there as an intern in 1986, including a rotation in the burns and accident ward, and wrote about it in 'Two Women' (Al-Youm Al-Gedid, 2016)."},"year":1986,"source":"https://aktowfik.blogspot.com/2016/08/blog-post_10.html"},{"id":"al-salam-mosque-murshaha","name":{"ar":"مسجد السلام بالمرشحة","en":"Al-Salam Mosque, Al-Murshaha"},"kind":"mosque","lat":null,"lng":null,"text":{"ar":"صُلّي عليه ظهر الثلاثاء 3 أبريل 2018 في مسجد السلام بمنطقة المرشحة في طنطا، ومنه خرجت جنازته إلى المقابر وسط آلاف من قرائه وزملائه.","en":"His funeral prayer was held at noon on Tuesday 3 April 2018 at Al-Salam Mosque in Tanta's Al-Murshaha area, from where thousands of readers and colleagues walked with him to the cemetery."},"year":2018,"source":"https://www.elwatannews.com/news/details/3238603"},{"id":"qahafa-cemetery-grave","name":{"ar":"قبره في مقابر قحافة","en":"His grave in the Qahafa cemeteries"},"kind":"grave","lat":null,"lng":null,"text":{"ar":"ووري الثرى في مقابر الأسرة بقحافة في طنطا يوم 3 أبريل 2018. يقول مسؤول المقابر إن الزوار يأتون من أنحاء العالم، وإن الشباب زيّنوا القبر بالأشجار والورود، وتعلّق عليه في ذكرى ميلاده رسائل المحبين.","en":"He was buried in the family tomb in the Qahafa cemeteries of Tanta on 3 April 2018. The cemetery keeper says visitors come from all over the world, young readers planted trees and flowers on it, and fans pin letters to it on his birthday."},"year":2018,"source":"https://www.masrawy.com/news/news_regions/details/2018/4/3/1307264/%D8%AC%D8%AB%D9%85%D8%A7%D9%86-%D8%A3%D8%AD%D9%85%D8%AF-%D8%AE%D8%A7%D9%84%D8%AF-%D8%AA%D9%88%D9%81%D9%8A%D9%82-%D9%8A%D9%88%D8%A7%D8%B1%D9%89-%D8%A7%D9%84%D8%AB%D8%B1%D9%89-%D9%81%D9%8A-%D9%85%D9%82%D8%A7%D8%A8%D8%B1-%D9%82%D8%AD%D8%A7%D9%81%D8%A9-%D8%A8%D8%B7%D9%86%D8%B7%D8%A7"},{"id":"grave-first-anniversary-2019","name":{"ar":"قرّاؤه عند قبره في الذكرى الأولى","en":"Readers at his grave on the first anniversary"},"kind":"event","lat":null,"lng":null,"text":{"ar":"في 2 أبريل 2019 توافد شباب وفتيات على قبره منذ الصباح، فوضعوا الزهور وقرأوا الفاتحة وعلّقوا أوراقًا عليها مقتطفات من كلماته.","en":"On 2 April 2019 young readers came to his grave from the morning, laying flowers, reciting the Fatiha and pinning up notes with lines from his writing."},"year":2019,"source":"https://www.youm7.com/story/2019/4/2/صور-توافد-الشباب-على-قبر-العراب-أحمد-خالد-توفيق-لإحياء/4193158"},{"id":"tanta-book-fair-2018","name":{"ar":"معرض طنطا للكتاب يحمل اسمه (مدرسة الرافعي)","en":"Tanta Book Fair named after him (El-Rafei School)"},"kind":"event","lat":null,"lng":null,"text":{"ar":"أطلقت الهيئة المصرية العامة للكتاب اسمه على معرض طنطا الصيفي للكتاب في عام رحيله وخصّصت فعاليات لأعماله؛ وأقيم معرض طنطا الثالث بمدرسة الرافعي من 2 إلى 11 أغسطس 2018.","en":"The Egyptian General Book Authority named Tanta's summer book fair after him in the year of his death, with events devoted to his work; the third Tanta Book Fair was held at El-Rafei School from 2 to 11 August 2018."},"year":2018,"source":"https://www.youm7.com/story/2022/6/10/أحمد-خالد-توفيق-أُدرج-بمشروع-عاش-هنا-وأُطلق-اسمه-على/5795757"},{"id":"qaadet-ashab","name":{"ar":"«قعدة أصحاب» – لقاؤه الدوري بالشباب في طنطا","en":"'Qaadet Ashab' – his regular gathering with young people in Tanta"},"kind":"event","lat":null,"lng":null,"text":{"ar":"«قعدة أصحاب» لقاء كان يقيمه في طنطا بصورة دورية، ونُظمت ضمنه مسابقة لرسم قصة مصورة بعنوان «الاتجاه المشاكس» عام 2010. لم يُذكر مكان اللقاء.","en":"'Qaadet Ashab' (Friends' Sitting) was a gathering he held regularly in Tanta; in 2010 it ran a comics contest on the story 'The Contrary Direction'. The venue is not named."},"year":2010,"source":"https://aktowfik.blogspot.com/2010/08/blog-post_9618.html"},{"id":"al-murshaha-canal","name":{"ar":"المرشّحة – «نيل طنطا»","en":"Al-Murshaha – 'Tanta's Nile'"},"kind":"other","lat":null,"lng":null,"text":{"ar":"مصرف المياه الذي يصر أهل طنطا على تسميته «كورنيش»، وكان يفضّل الجلوس عنده على كافيهات الشباب المغلقة؛ ومنه اسم سلسلة مقالاته «ثرثرة فوق المرشّحة» في التحرير (2013).","en":"The drainage canal Tanta's people insist on calling a 'corniche'; he preferred sitting by it to closed-in youth cafés, and named his Al-Tahrir column series 'Chatter on Al-Murshaha' (2013) after it."},"year":2013,"source":"https://aktowfik.blogspot.com/2013/10/blog-post_21.html"},{"id":"sayed-badawi-mosque-moulid","name":{"ar":"مسجد السيد البدوي ومولده","en":"Al-Sayyid al-Badawi Mosque and its moulid"},"kind":"mosque","lat":30.7836,"lng":30.9989,"text":{"ar":"كتب في «إنه أكتوبر» (التحرير، 2015) أن أكتوبر عند «الطنطاوية مثلي» موسم زحف المئات إلى مولد السيد البدوي، وذكر المسجد في مقالات أخرى، منها حديثه عن حريق 2012 الذي كاد يبلغ ما حوله.","en":"In 'It's October' (Al-Tahrir, 2015) he wrote that for Tantawis like him October is the season of crowds arriving for al-Sayyid al-Badawi's moulid; the mosque appears in other columns too, including his account of the 2012 fire that nearly reached its surroundings."},"year":2015,"source":"https://aktowfik.blogspot.com/2015/10/blog-post_15.html"},{"id":"shari-al-bahr-old-tanta","name":{"ar":"شارع البحر وسينما جندولا","en":"Shari' al-Bahr and Cinema Gondola"},"kind":"other","lat":null,"lng":null,"text":{"ar":"في «موضوع محلي جدًا» (التحرير، 2014) رثى طنطا القديمة مع توسعة شارع البحر وقطع أشجاره، وتذكّر سينما جندولا عند تقاطع شارعي الحلو وحسن رضوان التي صارت مقهى، وسينما أوبرا التي صارت قاعة أفراح.","en":"In 'A Very Local Topic' (Al-Tahrir, 2014) he mourned old Tanta as Shari' al-Bahr was widened and its trees cut, recalling Cinema Gondola at the corner of El-Helw and Hassan Radwan streets, now a café, and Cinema Opera, now a wedding hall."},"year":2014,"source":"https://aktowfik.blogspot.com/2014/07/blog-post_30.html"},{"id":"sales-company-fire-2012","name":{"ar":"حريق «شركة بيع المصنوعات»","en":"The fire at the 'Manufactured Goods Sales Company' store"},"kind":"other","lat":null,"lng":null,"text":{"ar":"شاهد من سطح بنايته حريق مبنى «شركة بيع المصنوعات» عام 2012، وكتب أن جزءًا مهمًا من تاريخ طنطا ومن ذكرياته قد احترق، وأن النار كادت تبلغ شارع الخان وسوق ناصر ومسجد السيد البدوي.","en":"He watched the 2012 fire at the 'Manufactured Goods Sales Company' building from his rooftop, writing that an important part of Tanta's history and of his memories had burned, and that it nearly reached Al-Khan Street, Souq Nasser and the Badawi mosque."},"year":2012,"source":"https://aktowfik.blogspot.com/2012/05/blog-post.html"},{"id":"mar-girgis-church-2017","name":{"ar":"كنيسة مار جرجس بطنطا","en":"St George (Mar Girgis) Church, Tanta"},"kind":"other","lat":null,"lng":null,"text":{"ar":"بعد تفجير الكنيسة في أحد الشعانين 9 أبريل 2017 كتب «في أحد الشعانين الدامي» (إضاءات) عن طنطا التي اكتشفت أن كونها بلدة هادئة لا يعفيها من طوفان الدم، متسائلًا كيف دخلت المتفجرات بهذه السهولة.","en":"After the church bombing on Palm Sunday, 9 April 2017, he wrote 'On a Bloody Palm Sunday' (Ida2at) about Tanta learning that being a quiet town did not spare it, asking how the explosives got in so easily."},"year":2017,"source":"https://aktowfik.blogspot.com/2017/04/blog-post_11.html"},{"id":"al-shifa-hospital-fiction","name":{"ar":"«مستشفى الشفاء» – مستشفى طنطاوي باسم زائف","en":"'Al-Shifa Hospital' – a Tanta hospital under a false name"},"kind":"fiction","lat":null,"lng":null,"text":{"ar":"في قصته «خذوها أنتم» (إضاءات، 16 مارس 2018، قبل رحيله بأسابيع) تدور الأحداث في «مستشفى الشفاء» بطنطا؛ قال إن الاسم زائف وإن القصة حقيقية، وبطلها الطبيب عادل الذي يقع عليه عبء كل شيء.","en":"His story 'You Take Her' (Ida2at, 16 March 2018, weeks before his death) is set in 'Al-Shifa Hospital' in Tanta; he says the name is invented but the story true, centred on Dr Adel, who carries the whole place."},"year":2018,"source":"https://aktowfik.blogspot.com/2018/03/blog-post_16.html"}];
window.AKT.handwriting = [{"title":{"ar":"ثلاثمئة توقيع بخط يده لوليد خيري","en":"Three hundred hand-signed cards for Walid Khairy"},"kind":"signature","year":null,"text":{"ar":"طلب منه القارئ وليد خيري أن يوقّع مجموعة من الكروت ليرسلها إلى قرّاء يطلبون نسخًا موقّعة، فأرسل إليه 300 توقيع بخط يده دون تأخير.","en":"Reader Walid Khairy asked him to sign a batch of cards to send to readers wanting signed copies; he promptly sent back 300 signatures in his own hand."},"url":"https://www.elwatannews.com/news/details/4094440","outlet":{"ar":"الوطن","en":"El Watan"}},{"title":{"ar":"توقيع على ورقة بيضاء لقارئة من طنطا","en":"A signature on a blank sheet for a Tanta reader"},"kind":"signature","year":2016,"text":{"ar":"التقت سارة حاتم به في مؤتمر علمي بطنطا عام 2016 وطلبت توقيعه على استحياء، فوقّع لها على ورقة بيضاء قائلًا «اتفضلي»، وما زالت تحتفظ بها.","en":"Sara Hatem met him at a scientific conference in Tanta in 2016 and shyly asked for his autograph; he signed a blank sheet for her with a simple 'here you go', which she still keeps."},"url":"https://www.elwatannews.com/news/details/6621347","outlet":{"ar":"الوطن","en":"El Watan"}},{"title":{"ar":"«ابق حيًا حتى اللقاء القادم.. اتصرف!» – إهداء «الهول» لتامر نجم","en":"'Stay alive till next time… manage!' – a dedication in Al-Hawl for Tamer Negm"},"kind":"dedication","year":null,"text":{"ar":"في حفل توقيع مجموعته «الهول» بمكتبة ألف في مصر الجديدة طلب منه تامر نجم إهداءً يتمنى له البقاء على قيد الحياة، فكتب: «إلى العزيز تامر نجم.. ابق حيًا حتى اللقاء القادم.. اتصرف!» وذيّله بتوقيعه.","en":"At the signing of his collection Al-Hawl at Alef Bookstore in Heliopolis, Tamer Negm asked for a dedication wishing him to stay alive; he wrote 'To dear Tamer Negm… stay alive till next time… manage!' and signed it."},"url":"https://manassa.news/stories/2967","outlet":{"ar":"المنصة","en":"Al-Manassa"}},{"title":{"ar":"إهداء «بخطه المنمق» إلى «إيمان (ماجي)»","en":"A dedication 'in his neat hand' to 'Eman (Maggie)'"},"kind":"dedication","year":2014,"text":{"ar":"روى محمد الدناصوري أنه وقف أكثر من ساعتين في معرض القاهرة للكتاب قبل رحيله بنحو أربع سنوات ليحصل على إهداء للفتاة التي يحبها، فكتب الإهداء باسم «إيمان (ماجي)» بخطه المنمّق على العدد الأخير من «ما وراء الطبيعة»، وصارت صاحبته زوجته فيما بعد.","en":"Mohamed El-Dennasoury queued over two hours at the Cairo Book Fair about four years before his death for a dedication to the girl he loved; he wrote it to 'Eman (Maggie)' in his neat hand on the last issue of Ma Wara'a al-Tabi'a. She later became El-Dennasoury's wife."},"url":"https://manassa.news/stories/2943","outlet":{"ar":"المنصة","en":"Al-Manassa"}},{"title":{"ar":"نسخة «يوتوبيا» موقّعة لكاتبة المقال","en":"A signed copy of Utopia for the article's writer"},"kind":"dedication","year":2008,"text":{"ar":"يذكر كاتب مقال ArabLit «أحمد خالد توفيق، عبقري» أنه شرّفه بتوقيع روايته «يوتوبيا» في عام صدورها، ولا ينقل نص الإهداء.","en":"The author of ArabLit's 'Ahmed Khaled Tawfik, Genius' recalls being honoured with his signature on Utopia in the year it came out; the wording of the inscription is not given."},"url":"https://arablit.org/2020/11/05/ahmed-khaled-tawfik-genius/","outlet":{"ar":"ArabLit","en":"ArabLit"}},{"title":{"ar":"حفل توقيع «في ممر الفئران» بديوان الزمالك","en":"Signing of In the Rat Path at Diwan Zamalek"},"kind":"dedication","year":2016,"text":{"ar":"إعلان عن حفل توقيع ومناقشة روايته «في ممر الفئران» بمكتبة ديوان فرع الزمالك يوم الخميس 11 أغسطس 2016، حيث وقّع نسخ القرّاء.","en":"Announcement of the signing and discussion of his novel In the Rat Path at Diwan's Zamalek branch on Thursday 11 August 2016, where he signed readers' copies."},"url":"https://www.youm7.com/story/2016/7/20/أحمد-خالد-توفيق-يوقع-روايته-فى-ممر-الفئران-بديوان-الزمالك/2806661","outlet":{"ar":"اليوم السابع","en":"Youm7"}},{"title":{"ar":"«القصاصة ما زالت في جيبي» – عن قصاصاته اليومية «بخط لا يُقرأ»","en":"'The Slip Is Still in My Pocket' – his daily notes 'in an unreadable hand'"},"kind":"note","year":2010,"text":{"ar":"في مقاله بمجلة الشباب (30 سبتمبر 2010) وصف القصاصة المربعة التي يحملها كل صباح، على وجه مهامه وعلى الآخر أفكاره المفاجئة، مكتوبة «بخط لا يُقرأ» حتى عليه هو، ويروي كيف قرأ طبيب امتياز كلمة «المرآة» فيها «المرأة».","en":"In his Al-Shabab column (30 September 2010) he described the square slip he carried each morning, with tasks on one side and sudden ideas on the other, written 'in an unreadable hand' even to him, and how an intern misread 'the mirror' on it as 'the woman'."},"url":"https://insaneyat.com/القصاصة-مازالت-في-جيبي-خالد-توفيق/","outlet":{"ar":"مجلة الشباب (منقول في إنسانيات)","en":"Al-Shabab magazine (via Insaneyat)"}}];
